88  SEG	dc.L TaskMasterDA-1		;$5F0E added 02 Oct 88  SEG	dc.l CompileString-1	;$600E added 10/20/88 Dan O.	dc.l NewWindow2-1		;$610E added 10/26/88 Dan O.	dc.l ErrorWindow-1		;$620E added 1/9/89 Konstantin*** 6.0	dc.l GetAuxWindInfo-1	;$630E added 19-Jan-91 DAL	dc.l DoModalWindow-1	;$640E added 19-Jan-91 DAL	dc.l MWGetCtlPart-1		;$650E added 19-Jan-91 DAL	dc.l MWSetMenuProc-1	;$660E added 19-Jan-91 DAL	dc.l MWStdDrawProc-1	;$670E added 19-Jan-91 DAL	dc.l MWSetUpEditMenu-1	;$680E added 19-Jan-91 DAL	dc.l FindCursorCtl-1	;$690E added 19-Jan-91 DAL	dc.l ResizeInfoBar-1	;$6A0E added 5-Mar-91 DAL	dc.l HandleDiskInsert-1	;$6B0E added 12-Apr-91 DAL*** 6.1	dc.l UpdateWindow-1		;$6C0E added 6-Mar-92 DAL	EXPORT ENDFPTENDFPT	ENDPWindowUpdateCount	proc export		;added 24-Sep-90 DAL	dc.w 0	EndP;=========================================;        Initialize	Window Manager;=========================================;;  IN:     PUSH:WORD - ID to use.;; OUT:     Nothing.;WindStartup	PROC	import SelfMod1Low,SelfMod1High,SelfMod2Low,SelfMod2High	import DiskSwap640Hndl,DiskSwap320HndlnewID	equ 9	jsl IncBusyFlg	phd	Save current zero page.	tax	Am I already initialized?	beq ok1	phb	jmp pop2bytesok1*** added 16-Sep-91 DAL -- pre-locate the disk-swap icons	pha	pha	pea $8001	;rIcon	pea $07ff	pea $0006	;disk-swap 640	_LoadResource	pla	sta >DiskSwap640Hndl	pla	sta >DiskSwap640Hndl+2	pha	pha	pea $8001	;rIcon	pea $07ff	pea $0106	;disk-swap 320	_LoadResource	pla	sta >DiskSwap320Hndl	pla	sta >DiskSwap320Hndl+2*** end 16-Sep-91*** added 27-Sep-90 DAL (self-modify references to 640-solid color table)	phb	phk	plb	stz WindowUpdateCount	;as long as we have B right, zero this here	pha	pha	_Get640Colors	pla	sta SelfMod1Low+1	sta SelfMod2Low+1	pla	sta SelfMod1High+1	sta SelfMod2High+1	plb*** end of 27-Sep-90 addition*** added 12-Apr-91 DAL -- initialize the disk-insert stuff	pha	pha	pea $2000	;18-Apr-91 DAL -- init everything to current (not offline)	pea 0	_HandleDiskInsert	pla	pla*** added 12-Apr-91 DAL*** added 20-May-91 DAL -- try to load and start QDAux if it isn't already here	pea 0	_QDAuxStatus	pla	bne @haveQDAux	pea $0012	;tool set = QDAux	pea $0304	;version = 3.4	_LoadOneTool	_QDAuxStartUp@haveQDAux*** end of 20-May-91 DAL;; --- Get zero page	to use from Event Manager and use it from now on -----;	pha	Space for returned zero page.	_DoWindows	Ask Event Manager for zero page.	pld	Switch to returned zero page.;	tdc	Pass direct page pointer to WAP.	jsr setWAP;;; --- Clear my half	of my direct page -----------------------;	ldx #$7Eclearzp	stz <$80,x	dex	bpl clearzp;;; --- Allocate a data area block -----------------------------;	lda newID,s	My memory ID.	sta <MyID;	lda #RAMSIZE	Size of data area needed.	jsr allocate	sta <work	Handle of data area.	stx <work+2	lda [<work]	Dereference handle.	sta <data	Store pointer to data area.	ldy #2	lda [<work],y	sta <data+2;;; --- Initialize data area --------------------------------;	lda #0	ldy #RAMSIZE-2lop1	sta [<data],y	dey	dey	bpl lop1;	jsr pushscInfo	ldy #scrn2scrn+PP_SrcInfo	jsr getPointer;	jsr pushscInfo	ldy #scrn2scrn+PP_DesInfo	jsr getPointer;	jsr pushblitsrc	ldy #scrn2scrn+PP_SrcRect	jsr getPointer;	jsr pushblitdes	ldy #scrn2scrn+PP_DesRect	jsr getPointer;;; --- Initialize Manager's variables ----------------------;	ldy #defwindclr	Set current window color table pointer	lda #def_color	to the default.	sta [<data],y	lda #def_color>>16	iny	iny	sta [<data],y;	lda #docDefProc	Stuff address of doc window defProc in	ldy #wmgr_wind+wDefProc window manager's dummy window record	sta [<data],y	cause Word Perfect uses it as a window.	lda #docDefProc>>16	iny	iny	sta [<data],y;	jsr alloc_rgn	Allocate a region for the desktop.	sta <GrayRgn	stx <GrayRgn+2;	jsr initres	Do additional initialization for mode.;	phb	jmp pop2bytes;;; = = = = = = = = =	= = = = = = = = = =	= = =;          Common code.; = = = = = = = = =	= = = = = = = = = =	= = =;;   IN:    y = offset into data area to	store LONG value.;          LONG value on stack.;;  OUT:    LONG value removed from stack and stored in data	area.;getPointer		; ;	plx;	pla	sta [<data],y	iny	iny	pla	sta [<data],y;	phx	rts;	ENDP;;;=====================================================;        Set up in current Screen Resolution.;=====================================================;;   IN:    Nothing.;  OUT:    Nothing.;WNewRes	PROC;;;	jsr setup;	jsr save_port;	jsr closeWMgrport	Close Window Manager's current port.;	jsr initres	Make needed initialization.;;; --- Reinitialize bounds of all window	ports --------------------;	lda <topwind	ldx <topwind+2	bra enter1;lop1	ldy #scInfo+PortSCB	lda [<data],y	Get current SCB byte.	ldy #wport+GP_PortInfo+PortSCB	sta [<wind],y	Set proper SCB byte.;	and #$0080	Get mode flag.	php	lda #320	Max port width for 320 mode.	plp	beq ok1	320 or 640 mode?	asl a	Double width for 640 mode.ok1	ldy #wport+GP_PortInfo+PBounds+x1	clc	adc [<wind],y	ldy #wport+GP_PortInfo+PBounds+x2	sta [<wind],y;	jsr moveWMgrOnWind	Move Window Manager's port on window.	ldx #wCalcRgns	jsr dispatch	Trash 'rect' and 'wrect'.	jsr moveWmgrBack	Move Window Manager's port back.;	ldy #2	Next window.	lda [<wind],y	tax	lda [<wind];enter1	sta <wind	stx <wind+2	ora <wind+2	Any more windows?	bne lop1;	jsr calc_vis	jsr restore_port;exit	phb	jmp pop0bytes	ENDP;;;===========================================;        Initialize	for resolution.;===========================================;initres	PROC;	IMPORT pushLocInfo1;;; --- Open Window Manager's port -------------------------;	jsr save_port	Save current port.;	jsr openWMgrport	Open Window Manager's port.;	jsr pushscInfo	Pass address of scInfo.	_GetPortLoc	Get the parameters of the screen.;	jsr pushLocInfo1	Pass address of locInfo1.	_GetPortLoc	Get the parameters of the screen.;;; --- Initialize my	variables for mode ------------------;	ldy #scInfo-1	lda [<data],y	and #$8000	ldy #screenMode	sta [<data],y	tay	bne do640;;; ------ Initialize	for 320 mode -------------------------;	ldx #1	Thickness of vertical lines.	lda #wind320	320 icon font.	ldy #P_SOLID+$B0	Default desktop pattern.	bra store1;;; ------ Initialize	for 640 mode --------------------------;do640	ldx #2	Thickness of vertical lines.	lda #wind640	640 icon font.	ldy #P_SOLID+$D0	Default desktop pattern.store1	sty <deskpatt	Initialize desktop pattern.	ldy #$4000	sty <deskpatt+2	ldy #fontHandle	Initialize font handle.	sta [<data],y	Put address of font	into dummy handle.	lda #wind320>>16	iny	iny	sta [<data],y	ldy #lineW	Initialize thickness of vertical lines.	txa	sta [<data],y	jsr pushfontHandle	Push pointer to fontHandle.	pla	ldy #windIconFont	sta [<data],y	Store the icon font	handle.	pla	iny	iny	sta [<data],y	pei <GrayRgn+2	Pass handle of region.	pei <GrayRgn	jsr pushscreen	Pass pointer to screen bounds.	_RectRgn	Make desktop region	the entire screen.;;; --- Initialize global widths and heights ------------------;; ------- Height of	window's title bar ----------------------;	jsr pushwork	Push address of work.	_GetFontInfo	lda <work	Font's ascent,	clc	adc #3	Pad the top.	ldy #titleYPos	sta [<data],y	Y position to print	title in title bar.	clc	adc <work+2	plus decent is the height.	adc #2	Pad bottom.	ldy #titleHeight	sta [<data],y	That's the height of title bars.;; --- Compute width	and height of close	and zoom box --------------;	pha	pha	_GetFontID	pha	Space for current font.	pha	_GetFont	Get handle of current font.	ldy #windIconFont+2	Pass handle of icon	font.	lda [<data],y	pha	dey	dey	lda [<data],y	pha	_SetFont	Switch to window icon font.	pea 0	Close box character.	jsr pushrect	Place to store bounds.	_CharBounds	lda <rect+y2	Compute height of close box icon.	sec	sbc <rect+y1	ldy #closeHeight	sta [<data],y	Keep height of close box (and zoom).	lda <rect+x2	Compute width of close box icon.	sec	sbc <rect+x1	ldy #closeWidth	sta [<data],y	Keep width of close	box (and zoom).	_SetFont	Restore original font.	_SetFontID	pea 8	Check if there is another desktop pattern.	pha	pha	_Desktop	brl restore_port	Restore original port.	ENDP;=================================================;          Return status of Window Manager.;=================================================;;   IN:    None.;;  OUT:    WORD - 1	if active, 0 if not	active.;;; 24-Sep-90 DAL; Now returns with the carry set if there are any windows; being updated.;WindStatus	PROC	**	tax**	beq store**	lda #$0012	Dan O. version number.**store	sta 7,s	Return status.	lda >WindowUpdateCount	;added 24-Sep-90	cmp #1		;added 24-Sep-90	lda #0	rtl	ENDP;=========================================;          Shut down Window Manager.;=========================================;;   IN:  None.;;  OUT:  None.;WindReset	PROC	jsl IncBusyFlg	phd	bra quicky	ENTRY WindShutDownWindShutDown		cmp #0	See if we are active	bne @continue 	if a-reg is zero, we are not active!	clc	rtl@continue	jsl IncBusyFlg	phd	tcd;; --- Close every window, in every way -------------------------;	bra enter1lop1	lda <topwind	jsr get_portp2	phx	; push window pointer for closewindow	pha	ldy #wFrame	lda [<topwind],y	and #$FFFF-f_Vis	sta [<topwind],y	_CloseWindow;enter1	lda <topwind+2	tax	ora <topwind	bne lop1*** 21-Jan-91 DAL*** If there's an AuxWindHandle, dispose of it.	lda <AuxInfoHandle+1	beq @noHandle	pei <AuxInfoHandle+2	pei <AuxInfoHandle	_DisposeHandle	stz <AuxInfoHandle+1@noHandle*** end of 21-Jan-91 DAL;;; --- refresh the desktop ----------------------------------;	PushLong #ScreenRect	_RefreshDeskTop;;; --- Free desktop region ----------------------------------;	jsr pushGray	_DisposeRgn;;; --- Close the Window Manager's port ----------------------;	jsr closeWMgrport	Close Window Manager's port.;	_CtlReset	Shutdown the Control Manager.;;; --- Free allocated data area.;	pha	pha	pei <data+2	Find handle of data area.	pei <data	_FindHandle	_DisposeHandle;;; --- Set my Tool Locator variable to zero ------------------;quicky	lda #0	Clear WAP.	jsr setWAP;	phb	jmp pop0bytes	All done.ScreenRect	dc.w 0,0,200,640	ENDP;;;===============================;          Call SetWAP.;===============================;;   IN:    a = value to pass to WAP.;setWAP	PROC;		;using equates;;	ldx #0	phx	pea WindToolNum	Pass Window Manager	tool number.	phx	pha	_SetWAP	Tell Tool Locator about it.	rts	ENDP;;;=========================================;        Stuff any update messages;        into event	record.;=========================================;;   IN:  PUSH:LONG - pointer to event record.;;  OUT:  WORD - 1 if update event passed, 0 if no update event found.;CheckUpdate	PROC;		;using equates;eventRec	equ 9RetFlag	equ eventRec+4;;	jsl IncBusyFlg	phd	Save orginal zero page.	tcd	Switch to my zero page.;	lda eventRec,s	Move event pointer into 'workptr'.	sta <workptr	lda eventRec+2,s	sta <workptr+2;;; --- Search window	list for windows with valid update regions ----------;	lda <topwind	Start with the top most window.	ldx <topwind+2lop	stx <wind+2	sta <wind	ora <wind+2	beq exit	Any more windows?;; ------- Is the window even visible? ---------------------------;	jsr testVis	Test the window's F_VIS flag.	beq nextwind	Only check visible windows.;; ------- Check if window's update region is empty -----------------;	pha	Space for result.	ldy #wupdateRgn+2	jsr pushandle	Push window's update region handle.	_EmptyRgn	Check if region is empty.	pla	bne nextwind	Empty?;; ------- Pass update information in event record -------------------;	lda #6	Set event code.	sta [<workptr];	jsr get_portptr	Compute pointer to window's port.;	ldy #message	Return pointer to window	sta [<workptr],y	iny	iny	txa	sta [<workptr],y	lda #TRUE	Update flag.	bra exit	That's it.;nextwind	ldy #2	Next window in list.	lda [<wind],y	tax	lda [<wind]	bra lop;;exit	sta RetFlag,s	0 = no update, not 0 = update.	phb	jmp pop4bytes	ENDP;;;========================================;          Redraw entire desktop.;========================================;;   IN:    PUSH:LONG - pointer to RECT,	or zero for whole screen.;  OUT:    None.;Refresh	PROC;;;badRect	equ 9;;	tax	bne @Continue	lda #2	sec	rtl@Continue	jsl IncBusyFlg	phd	Save zero page.	tcd	Switch to my zero page.;;; --- Check if caller wants whole screen -------------------------------;	lda badRect+2,s	tay	lda badRect,s	tax	bne skip1	tya	bne skip1	Use default whole screen RECT?;	jsr pushGP_Bounds	Push pointer to my port's bounds.	plx	ply;;; --- Redraw the clobbered area ----------------------------------------;skip1	sty <work+2	Save address of RECT to redraw.	stx <work;	jsr alloc_rgn	Allocate a temp work region, 'rgnptr'.;	jsr pushrgnptr	Pass address of clobbered region.	pei <work+2	Pass address of clobbered RECT.	pei <work	_RectRgn	Set clobbered region to clobbered RECT.;	jsr setwmgrport	jsr fullport;	pei <GrayRgn+2	Desktop,	pei <GrayRgn	jsr pushrgnptr	AND clobbered region.	jsr pushrgnptr	_SectRgn	rgnptr = rgnptr AND	GrayRgn.;	lda <topwind	Draw every window.	sta <wind	lda <topwind+2	sta <wind+2	jsr paintonedown;	jsr disposeRgnPtr	Free temp work region.;	jsr restore_port	Restore original port.;	phb	jmp pop4bytes	Restore zero page.	ENDP;;;======================================================;        Return Window Manager's Version Number;======================================================;  IN:   Nothing; OUT:   WORD - version number.;WindVersion	PROC	lda #$0304	;1-Apr-93 SS	sta 7,s	brl RealFastExit	ENDP;======================================================;        Return pointer to Window Manager's port.;======================================================;  IN:   Nothing; OUT:     LONG - pointer to Window Manager's port.;GetWMgrPort	PROC;;result	equ 9;	jsl IncBusyFlg;	phd	tcd;	jsr pushport	Push address of Window Manager port.	pla	Return address of Window Manager port.	plx	bra return;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = =;        Return pointer to current active window.;100= = = = = = = =	= = = = = = = = = =	= = = = = = = = =;;  IN:   Nothing;; OUT:   LONG - pointer to current active window's port.;	ENTRY FrontWindowFrontWindow		;       ;	jsl IncBusyFlg;	phd	tcd;	jsr find_top	Find the top most visible window.	jsr get_portp2	Convert window pointer to port pointer.	bra return;;; = = = = = = = = =	= = = = = = = = = =	= = = =;          Return pointer to first;          window in window list.;110= = = = = = = =	= = = = = = = = = =	= = = =;;  IN:   Nothing;; OUT:   LONG - pointer to first window	in window list, zero if none.;	ENTRY GetFirstWindowGetFirstWindow		;       ;;	jsl IncBusyFlg	phd	tcd;	lda <topwind	Return pointer to top window port.	ldx <topwind+2	bne ok1	tay	beq returnok1	clc	adc #wport	bcc return	inx;return	sta result,s	Return pointer to top window port.	txa	sta result+2,s;	phb	jmp pop0bytes;	ENDP;;;===============================================;        Swap Window Manager Icon Font.;===============================================;;   IN:    PUSH:LONG - handle of new Window Manager icon font, -1 for none.;;  OUT:    LONG - current (before swap)	icon font.;SetWMgrIcons	PROC;;newFont	equ 9oldFont	equ newFont+4;;	jsl IncBusyFlg	phd	tcd;	ldy #windIconFont	Return old font.	lda [<data],y	sta oldFont,s	iny	iny	lda [<data],y	sta oldFont+2,s;	lda newFont+2,s	Use new font?	bmi exit;	sta [<data],y	Initialize new icon	font.	dey	dey	lda newFont,s	sta [<data],y;exit	phb	jmp pop4bytes	ENDP;;;===============================================================;          Return pointer to Window Manager globals.;===============================================================;GetWindowMgrGlobals	PROC;;result	equ 9;;	jsl IncBusyFlg	phd	tcd;	lda <data	sta result,s	lda <data+2	sta result+2,s;	phb	jmp pop0Bytes	ENDP;;;==================================================;          Setup to	draw window frame.;==================================================;;   IN:    PUSH:LONG - pointer to window RECORD to setup for.;	EXPORT StartFrameDrawingStartFrameDrawing	PROC;		;using equates;theWindow	equ 9;;	jsl IncBusyFlg	phd	Save caller's direct page pointer.	tcd	Switch to Window Manager's direct page.;	lda theWindow,s	Pass pointer to window record.	sta <wind	lda theWindow+2,s	sta <wind+2;	jsr pushGray	Pass handle to desktop, source 1.	ldy #wstrucRgn+2	Pass handle window's StructRgn.	jsr pushandle	jsr pushclip	Pass handle of region for result.	_SectRgn	Intersection of strucRgn and desktop.;	jsr SubStructLoop	Subtract all windows above.	jsr moveWMgrOnWind	Move Window Manager	port over window.;	phb	jmp pop4bytes	ENDP;;;==================================================;          Undo setup to draw window frame.;==================================================;;   IN:    No inputs.;          StartFrameDrawing must have been called.;	EXPORT EndFrameDrawingEndFrameDrawing	PROC;	jsl IncBusyFlg	phd	Save caller's direct page pointer.	tcd	Switch to Window Manager's direct page.;	jsr moveWMgrBack	jsr fullPort;	phb	jmp pop0bytes	ENDP;;;            APPEND	WREGION.ASM	TITLE 'Apple IIGS Window Manager                   WREGION.ASM';;          Copyright Apple Computer, Inc. 1986,1987,1988;          All rights reserved;          Written by Dan Oliver;;;======================================================;          Subtract	region from update region.;======================================================;;   IN:    PUSH:LONG - handle of region	to take from window's update region.;          Current port is window's.;;  OUT:    None.;ValidRgn	PROC;;;	ldx #1	Subtract region flag.	bra common100;;; = = = = = = = = =	= = = = = = = = = =	= = = =;          Add region to update region.;100= = = = = = = =	= = = = = = = = = =	= = = =;;   IN:    PUSH:LONG - handle of region	 to be added to window's update region.;          Current port is window's.;;  OUT:    None.;	ENTRY InvalRgnInvalRgn		;       ;badRgn	equ 9;;	ldx #0	Add flag.;common100		jsl IncBusyFlg	phd	Save caller's zero page.	tcd	Switch to my zero page.;	jsr chg_update	Add the region to the update region.;	phb	jmp pop4bytes;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;          Subtract	RECT to update region.;110= = = = = = = =	= = = = = = = = = =	= = = = = = =;;   IN:    PUSH:LONG - pointer to RECT to take from window's update region.;          Current port is window's.;;  OUT:    None.;	ENTRY ValidRectValidRect		;       ;;	ldx #1	Subtract flag.	bra common120;;; = = = = = = = = =	= = = = = = = = = =	= = = =;          Add RECT	to update region.;120= = = = = = = =	= = = = = = = = = =	= = = =;;   IN:    PUSH:LONG - pointer to RECT to be added to window's update region.;          Current port is window's.;;  OUT:    None.;	ENTRY InvalRectInvalRect		;       ;	ldx #0	Add flag.;common120		jsl IncBusyFlg	jsr init_rgn	Allocate and initialize temp region.;	jsr disposeRgnPtr	Free temp region.;	phb	brl pop4bytes;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;       Get window pointer from current	port;130= = = = = = = =	= = = = = = = = = =	= = = = = = =;init_rgn	ply	Get return address.;	phd	Save caller's zero page.	tcd	Switch to my zero page.;	phy	Put return address back.;;; --- Allocate and initialize a temp region -------------;	stx <work	Save operation flag.;	jsr alloc_rgn	Get temp region.;	jsr pushrgnptr	Set temp = to given	RECT.	lda 17,s	Pass address of RECT.	pha	lda 17,s	pha	_RectRgn;	lda <rgnptr	Replace pointer to RECT with region.	sta 11,s	lda <rgnptr+2	sta 13,s;	ldx <work	Save operation flag.;;chg_update	stx <work	Save operation.;	jsr get_port;; --- Convert region to global coordinates ------------------;	lda 13,s	Region handle.	pha	lda 13,s	pha	ldy #wport+GP_Bounds+x1 Get window's port offset.	lda [<wind],y	eor #$FFFF	inc a	pha	dey	dey	lda [<wind],y	eor #$FFFF	inc a	pha	_OffsetRgn;;		            ; --- Add/Subtract region to update region ------------------------;	ldy #wupdateRgn+2	Starting region.	jsr pushandle	lda 17,s	Region to subtract.	pha	lda 17,s	pha	ldy #wupdateRgn+2	Region to place result.	jsr pushandle;	lda <work	Was that add or subtract?	beq add2;	_DiffRgn	Subtract region.	rts;add2	_UnionRgn	Add region	rts;	ENDP;;;=======================================================================;          Set the window's origin to draw.;          The caller should perform SetOrigin(0,0) when done.;=======================================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    None.;                Current port equals window's.;                Origin set.;StartDrawing	PROC;;;	jsr setup;	lda #wStartDrawing	Pass command to defProc.	jsr callProc2	Call window's defProc.;	phb	brl pop4bytes	ENDP;;;======================================;        Replace visRgn with;        visRgn AND	wupdateRgn.;======================================;;   IN:  PUSH:LONG - pointer to window's port.;;  OUT:  Nothing.;	EXPORT BeginUpdateBeginUpdate	PROC	jsr setup	lda >WindowUpdateCount	;added 24-Sep-90 DAL	inc a		;added 24-Sep-90 DAL	sta >WindowUpdateCount	;added 24-Sep-90 DAL	jsr startupdate	jsr get_portptr	Get pointer to window's port.	phx	pha	_SetPort	phb	brl pop4bytes;;; = = = = = = = = =	= = = = = = = = = =	= =;          Guts of BeginUpdate.;100= = = = = = = =	= = = = = = = = = =	= =;;   IN:    wind = window pointer.;;  OUT:    window's visRgn = update region.;          port = window's.;	EXPORT startupdatestartupdate		;       ;;; --- Convert updateRgn to local coordinates ------------------;	ldy #wupdateRgn+2	jsr pushandle	ldy #wport+GP_Bounds+x1 Get window's port offset.	jsr pushWlong	_OffsetRgn	Make update local to window.;;; --- updateRgn = updateRgn AND visRgn ------------------------;	ldy #wport+GP_VisRgn+2	jsr pushandle	Pass the visRgn handle.	ldy #wupdateRgn+2	Pass the update region handle.	jsr pushandle	ldy #wupdateRgn+2	Put the intersection of vis and	jsr pushandle	update into update.	_SectRgn	Get the intersection.;;; --- Switch the visRgn and updateRgn handles ----------;	jsr swapRgn;;; --- Switch to the	window's port ----------------------;	jsr save_port	Save the original port.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;          Replace visRgn with wupdateRgn.;110= = = = = = = =	= = = = = = = = = =	= = = = = = =;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    Nothing.;	EXPORT EndUpdateEndUpdate	jsr setup	lda >WindowUpdateCount	;added 24-Sep-90 DAL	dec a		;added 24-Sep-90 DAL	sta >WindowUpdateCount	;added 24-Sep-90 DAL	jsr finiupdate	phb	brl pop4bytes;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;          Guts to EndUpdate.;120= = = = = = = =	= = = = = = = = = =	= = = = = = =;;   IN:    wind = window pointer.;	EXPORT finiupdatefiniupdate;	jsr swapRgn	Exchange updateRgn and visRgn handles.;	ldy #wupdateRgn+2	jsr pushandle	Push updateRgn handle.	_SetEmptyRgn	Empty the update region.;	brl restore_port	Restore original port.;;	       ; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;        Swap updateRgn and visRgn handles.;130= = = = = = = =	= = = = = = = = = =	= = = = = = =;;   IN:    <wind = pointer to window.;swapRgn	ldy #wport+GP_VisRgn+2	jsr pushandle	Save the visRgn handle.;	ldy #wupdateRgn+2	jsr pushandle	Get the handle for updateRgn.	ldy #wport+GP_VisRgn Store wupdateRgn handle in visRgn.	pla	sta [<wind],y	iny	iny	pla	sta [<wind],y;	ldy #wupdateRgn	Store visRgn handle	in wupdate.	pla	sta [<wind],y	iny	iny	pla	sta [<wind],y	rts;	ENDP;;;========================================;        Redraw a clobbered region.;========================================;;   IN:  wind = window to start with, and go down list from	there.;        rgnptr = clobbered region.;;  OUT:  wind trashed.;        rgnptr trashed.;paintbehind	PROC;; --- Go down list and draw all windows	-----------;lop1	ldy #2	;Next window.	lda [<wind],y	tay	lda [<wind]	sta <wind	sty <wind+2;;	ENTRY paintonedownpaintonedown;	jsr PaintOne	;Paint the window.;	lda <wind	ora <wind+2	bne lop1;	rts;;; = = = = = = = = =	= = = = = = = = = =	= =;        Draw a single window.;100= = = = = = = =	= = = = = = = = = =	= =;;   IN:    wind = window to be drawn, zero to draw desktop pattern.;          rgnptr =	handle of region to	be redrawn (clobbered region).;          Current port = window manager's.;;  OUT:    rgnptr =	rgnptr - redrawn area.;	ENTRY PaintOnePaintOne;	lda <wind	Is window NIL?	ora <wind+2	bne gopaintone;;; --- Draw desktop in clobbered region -----------;	jsr pushrgnptr	jsr pushclip	_CopyRgn;	jsr PaintDesk	Fill the current port with desktop.;	jsr pushrgnptr	Clobbered region.	_SetEmptyRgn	Clear clobbered region, all painted.toExit100	brl exit100;;; --- Draw the given window in the given region ------------------;gopaintone	jsr testVis	Test the window's F_VIS flag.	beq toExit100	Don't draw invisible windows;	jsr pushrgnptr	Pass handle of clobbered region.	ldy #wstrucRgn+2	Pass handle window's StructRgn.	jsr pushandle	jsr pushclip	Pass clip region handle.	_SectRgn	ClipRgn = clobbered	and wind StructRgn;	jsr testclip	Is clip region empty?	bne toExit100;;; ------- There is something to draw -----------------------;	jsr clipabove	Subtract windows above 'wind' from clip	bne toExit100	Anything left in clip region?;;; --- Draw window's frame --------------------------------------;	jsr drawframe;;; --- Subtract redrawn area from clobbered region ----------;	jsr pushrgnptr	Clobbered region.	jsr pushclip	Subtract redrawn region from clobbered.	jsr pushrgnptr	Result in clobbered	region.	_DiffRgn	Clobbered = clobbered - redrawn.;;; --- Compute clobbered content region ------------------;	ldy #wcontRgn+2	Region 1, content region.	jsr pushandle	jsr pushclip	Region 2, clobbered	region.	jsr pushclip	Result into clip.	_SectRgn;;; --- Erase content	area to be redrawn -------------------------;	jsr pushclip	Content part needing to be redrawn.	ldx <wind+2	Pass address of window's background	lda <wind	pattern.	clc	adc #wport+GP_BkPat	bcc store100	inxstore100	phx	pha	_FillRgn	Draw floor of content area.;;; --- Add clobbered	content area to window's update region --------------;	jsr pushclip	Clobbered part of content region.	ldy #wupdateRgn+2	Current update region for window.	jsr pushandle	ldy #wupdateRgn+2	Result in window's update region.	jsr pushandle	_UnionRgn	Add the clobbered to the update.;exit100	jsr fullport	Set clip to full desktop.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;        Fill screen with desktop pattern.;110= = = = = = = =	= = = = = = = = = =	= = = = = = =;	ENTRY PaintDeskPaintDesk	IMPORT pushLocInfo1	IMPORT pushDataAddr	lda <deskpatt+2	Get format of desktop pattern.	and #$FF00	xba	cmp #$0080	beq readyPatt	cmp #$0040	beq makePatt	asl a	tax	jmp (@types,x)@types	dc.w customType	dc.w messageType;; --- Pattern pointer in deskpatt.;readyPatt	jsr pushscreen	Pass pointer to screen bounds.	pei <deskpatt+2	Pass address of fill pattern.	pei <deskpatt	_FillRect	Draw desktop.	rts;;; --- Pattern number in deskpatt.;makePatt	jsr pushscreen	Pass pointer to screen bounds.	ldy <deskpatt	Pass pattern number to generate.	lda <data	Pass pointer to global data area.	ldx <data+2	jsr makePattern	Generate pattern.	phx	Pass address of generated pattern	phy	_FillRect	Draw desktop.	rts;;; --- Call outside routine to draw desktop.;customType	ldx <deskpatt+1	Address of routine to draw desktop.	lda <deskpatt	jsl longCall	Make long distance call.	rts;;; --- deskpatt is a handle deskMessage that defines desktop.;messageType	ldy #4	Lock message.	lda [<deskpatt],y	pha		Save attributes.	ora #$8000	sta [<deskpatt],y;	pei <work+2		Save.	pei <work;	ldy #2	Dereference the message.	lda [<deskpatt],y	sta <work+2	lda [<deskpatt]	sta <work;	ldy #messFormat	Dispatch to message format handler.	lda [<work],y	asl a	tax	jsr (@formats,x);	pla		Restore.	sta <work	pla	sta <work+2;	ldy #4	Restore handle's attributes.	pla	sta [<deskpatt],y	rts;@formats	dc.w @pattern	0	dc.w @picture	1;;;----------------------------------------------------------;	Pattern message handler.;----------------------------------------------------------;@pattern	jsr pushscreen	Pass pointer to screen bounds.	jsr @getMessInfo	Pass pattern pointer.	phx	pha	_FillRect	Draw desktop.	rts;;;----------------------------------------------------------;	Picture message handler.;----------------------------------------------------------;@picture	jsr @getMessInfo		Store address of image in locInfo record.	ldy #LocInfo1+PixelImage	sta [<data],y	iny	iny	txa	sta [<data],y;	jsr pushLocInfo1		Pass pointer to LocInfo record.	lda #LocInfo1+PBounds	Pass pointer to source RECT.	jsr pushDataAddr	lda #0			Common need.	pha		Pass destination point.	pha	pha	_PPToPort	rts;;;------------------------------------------------------------------------------;	Compute pointer to messInfo part of message.;------------------------------------------------------------------------------;@getMessInfo	ldx <work+2	Compute pointer to info part of message.	lda <work	clc	adc #messInfo	bcc @ok100	inx@ok100	rts;	ENDP;;;==========================================================;        Compute visible region of window's content.;==========================================================;;   IN:    Nothing.;;  OUT:    Visible content computed for	every window.;          'wind' preserved.;calc_vis	PROC	EXPORT calc_vis2;	lda #0	Calc to bottom window.	tax;;;  IN: x/a = window to stop at, this window and below does not have its visRgn computed.;stopWindow	equ 1;calc_vis2	pei <wind	Saves.	pei <wind+2;	phx	Save window to stop at.	pha;	lda <FloorRgn+1	Is there a floor region?	beq skip1;	jsr pushGray	Copy desktop region	into FloorRgn.	pei <FloorRgn+2	pei <FloorRgn	_CopyRgn;;skip1	lda <topwind	Start with the top window.	ldy <topwind+2	bra enter1;lop1	jsr testVis	Test the window's F_VIS flag.	beq nextwind;;	ldy #wcontRgn+2	Pass handle of window's content.	jsr pushandle	jsr pushclip	Pass handle of clip	region.	_CopyRgn	clip = wcontRgn.;	jsr clipabove	Subtract all windows above.;	jsr pushclip	ldy #wport+GP_Bounds+x1 Get window's port offset.	jsr pushWlong	_OffsetRgn	Make clip local to window.;	jsr pushclip	Put visible content	into visRgn.	ldy #wport+GP_VisRgn+2	jsr pushandle	_CopyRgn;;	lda <FloorRgn+1	Is there a Floor region?	beq nextwind;	pei <FloorRgn+2	From the Floor region,	pei <FloorRgn	ldy #wstrucRgn+2	subtract the window's entire region,	jsr pushandle	pei <FloorRgn+2	and place the answer back in the Floor.	pei <FloorRgn	_DiffRgn;;;nextwind	ldy #2	Next window.	lda [<wind],y	tay	lda [<wind];enter1	sta <wind	sty <wind+2;	cmp stopWindow,s	Stop at this window?	bne lop1	tya	cmp stopWindow+2,s	bne lop1;;	jsr fullport	Reset Window Manager's clip.;	pla	Get rid of window to stop at.	pla;	pla	Restores.	sta <wind+2	pla	sta <wind	rts	ENDP;;;==================================================;        Remove any	thing that doesn't;        belong to 'wind from clip region.;==================================================;;   IN:  wind = window to start with.;;  OUT:  clip = intersection of clip region and desktop,;	   less windows above.;        Equal = FALSE if 'rgnptr' region is NIL.;clipgabove	PROC;		;using equates;;	jsr fullport	Set port to GrayRgn.	brl SubStructLoop;	ENTRY clipaboveclipabove		;       ;	jsr pushGray	Pass handle to desktop, source 1.	jsr pushclip	Pass handle of clip	region, source 2.	jsr pushclip	Pass handle of region for result.	_SectRgn	Intersection of clip and desktop.;	brl SubStructLoop	Subtract all windows above and exit.	ENDP;;;======================================;        Set current port (wmgr);        to GrayRgn	(desktop).;=======================================;fullport	PROC;	jsr pushGray	Clip to whole desktop.	jsr pushclip	_CopyRgn	rts	ENDP;;;================================================;        Subtract all windows above 'wind';        from clip region.;================================================;;   IN:  wind = window to start with.;        clip = region to subtract from.;;  OUT:  clip = clip region less windows above 'wind'.;        Equal = FALSE if 'rgnptr' is NIL.;SubStructLoop	PROC;		;using equates;;	lda <topwind	Start subtracting from top window.	ldx <topwind+2	bra enter1;lop1	ldy #wframe	Is this window visible.	lda [<work],y	and #F_VIS	beq nextwind	Don't subtract invisible windows.;	jsr pushclip	Pass region handle,	source 1.	ldy #wstrucRgn+2	lda [<work],y	pha	dey	dey	lda [<work],y	pha	Pass window's StructRgn, source 2.	jsr pushclip	Region handle, destination.	_DiffRgn	Find the difference.;;nextwind	ldy #2	Get pointer to next	window.	lda [<work],y	tax	lda [<work]enter1	sta <work	stx <work+2;	cmp <wind	Have we reached the	given window?	bne lop1	cpx <wind+2	bne lop1;exit	brl testclip	Set flag to empty or not and return.	ENDP;;;==================================================;        Test if region in 'rgnptr' is NIL.;==================================================;;   IN:  rgnptr = handle of region to check.;;  OUT:  Equal is FALSE (a=nonzero) if 'rgnptr' is empty.;testrgnptr	PROC;		;using equates;;	pha	Space for returned value.	jsr pushrgnptr	Pass handle in 'rgnptr'.	bra testrgn;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;        Test if clip region is empty.;100= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:  Clip region to check is current port.;;  OUT:  Equal is FALSE (a=nonzero) if clip region is empty.;	ENTRY testcliptestclip		;       ;	pha	Space for returned value.	jsr pushclip	Pass handle of clip	region.;testrgn	_EmptyRgn	Is the region empty?	pla	Set return flag.	rts;	ENDP;;;============================;        Edit Desktop;============================;;   IN:  PUSH:WORD - operation number:;	                  0	= subtract region from desktop.;	                  1	= add region to desktop.;	                  2	= return handle of desktop region.;	                  3	= set handle of desktop region.;	                  4	= return desktop pattern.;	                  5	= set new desktop pattern.;	                  6	= return visible desktop.;	                  7	= install background region.;	                  8 = check for new desktop pattern in message center.;        PUSH:LONG - input parameter.;;  OUT:  LONG - output parameter.;Desktop	PROC;	IMPORT allocate3;in_param	equ 9operation	equ in_param+4out_param	equ operation+2;;	tax	bne @Continue	lda #2	sec	rtl@Continue;	jsl IncBusyFlg;	phd	Save orginal zero page.	tcd	Switch to my zero page.;	lda operation,s	asl a	tax	lda >op_table,x	pha	lda in_param+4,s	tax	lda in_param+2,s	rts	Go to operation.;op_table	DC.W FromDesk-1		0	DC.W ToDesk-1		1	DC.W GetDesktop-1		2	DC.W SetDesktop-1		3	DC.W GetDeskPat-1		4	DC.W SetDeskPat-1		5	DC.W VisDesktop-1		6	DC.W BackRegion-1		7	dc.w desktopMessage-1	8;;; --- Check for new desktop pattern message.;GetMessage	equ 2	Message command.DeskMessage	equ 2	Message type.;desktopMessage	lda #24	Number of bytes to allocate.	ldx #0	Handle attributes.	ldy <MyID	jsr allocate3	sta <work	Save handle.	stx <work+2;	pea GetMessage	Pass action value.	pea DeskMessage	Pass type of message.	phx	Pass handle to MessageCenter.	pha	_MessageCenter	Parameters on stack.	bcc @ok1	Was a pattern message found?;	pei <work+2	pei <work	_DisposeHandle	Handle not used or needed.	brl exit2;@ok1*** added 12-Dec-91 DAL -- if old pattern was pat/pic handle, dispose it	lda <deskpatt+2	and #$ff00	cmp #$0100	bne @notHandle	lda <deskPatt+2	and #$00ff	pha	pei <deskPatt	_DisposeHandle@notHandle*** end 12-Dec-91	lda <work	Set handle of desktop image.	sta <deskpatt	lda <work+2	ora #$0100	Set flag that tell format of data in deskpatt.	sta <deskpatt+2*** added 12-Dec-91 DAL -- tell anyone who cares of new message	pea 8	;reqCode = systemSaysNewDeskMsg	ldx #0	phx	;sendToAll	phx	phx	;target=NIL	phx	phx	;dataIn=NIL	phx	phx	;dataOut=NIL	_SendRequest*** end 12-Dec-91	brl exit2;;; --- Install a background region --------------------------------;BackRegion	sta <FloorRgn	stx <FloorRgn+2	brl exit2;;; --- Add/Subtract region from the desktop ------------------------;ToDesk		; FromDesk	pei <GrayRgn+2	Pass handle to current desktop region.	pei <GrayRgn	phx	Pass handle of given region.	pha	pei <GrayRgn+2	Put result in desktop region.	pei <GrayRgn;	ldx #UnionRgn	lda operation+12,s	Union of Diff call?	bne ok1	ldx #DiffRgnok1	jsl $E10000	Execute _UnionRgn or _DiffRgn.;	jsr calc_vis	Recompute visRgns for every window.	bra exit2;;;; --- Set new handle to desktop region ------------------------;SetDesktop	sta <GrayRgn	stx <GrayRgn+2;	jsr calc_vis	Recompute visRgns for every window.;;; --- Return handle	of desktop region -------------------------;GetDesktop	lda <GrayRgn	ldx <GrayRgn+2	bra exit;;; --- Install new desktop pattern -----------------------------;SetDeskPat*** added 12-Dec-91 DAL -- dispose of old pic/patt handle if present*** (Keep it if it matches the new one, so you can set the pattern to*** its current value to refresh!)	phx	pha	lda <deskPatt+2	and #$ff00	cmp #$0100	bne @noDispose	lda <deskPatt+2	cmp 3,s	bne @killOld	lda <deskPatt	cmp 1,s	beq @noDispose@killOld	lda <deskPatt+2	and #$00ff	pha	pei <deskPatt	_DisposeHandle@noDispose	pla	plx*** end 12-Dec-91	sta <deskpatt	stx <deskpatt+2	bra skip1	Paint new desktop.;;; ------ Return visible desktop ----------------------------------;VisDesktop	sta <rgnptr	Save given region.	stx <rgnptr+2;;; ------ Paint new desktop ---------------------------------------;skip1	jsr setwmgrport	Switch to Window Manager's port.	jsr fullport	Make sure port's clip is entire desktop.;	stz <wind	Subtract all windows from clip.	stz <wind+2	jsr SubStructLoop;	lda operation,s	cmp #6	bne skip2;	jsr pushclip	Copy visible desktop	jsr pushrgnptr	into given region.	_CopyRgn	bra skip3;skip2	jsr PaintDesk	Paint just the desktop.skip3	jsr fullport	Leave with Window Manager's port full.;	jsr restore_port	bra exit2;;; --- Return desktop pattern ----------------------------------;GetDeskPat	lda <deskpatt	ldx <deskpatt+2;exit	sta out_param,s	txa	sta out_param+2,s;exit2	phb	brl pop6bytes	ENDP;********************************************************************************	Export FakeReadMouseFakeReadMouse	PROC** Description:  	This routine can be used as a direct replacement for the*	ReadMouse misc tools call.  Its inputs and outputs are*	identical in every way to the real read mouse. The main *	difference is that this readmouse calls eventavail instead*	of going directly to the mouse. This allows journalling to*	take place.**	NOTE: This call Clears all bits of the mode byte.*** Inputs:   	Space	- Word*	Space	- Word*	Space	- Word*	ReturnAddr** Outputs:  	CurrentX (Word)	- Y position in global coordinants*	CurrentY (Word)	- X position in global coordinants*	ButtonState (word)	- status of the buttons. (Mode clear)*	* External Refs:** Entry Points:********************************************************************************** First define a stack frame for our use@tempEvent	equ 1@xevent	equ @tempEvent+16@SaveDPage	equ @xEvent+2@ReturnAddr	equ @SaveDPage+2@ButtonState	equ @ReturnAddr+3@CurrentY	equ @ButtonState+2@CurrentX	equ @CurrentY+2;	phd	Save current direct	page.;	tsc	Make room for event	record.	sec	on the stack	sbc #@xevent+1	tcs	tcd;	pha	Space for returned flag.	pea 0	Looking for NULL event only.	pea 0	Pass pointer to event record.	inc a	NOTE: <A> still holds the direct	pha	page pointer at this point.	_EventAvail	plx	Get returned flag and ignore it.	lda <@tempEvent+10	get the mouse coordinants	sta <@CurrentY	lda <@tempEvent+12	sta <@CurrentX		lda <@tempEvent+14	get the button states	and #$00C0	strip off just the button status	eor #$00C0	xba	put it in the high byte	sta <@ButtonState		tsc	Remove the bogus event record 	clc	on the stack	adc #@xevent+1	tcs	pld	rtl	EndP;;===============================================;        Drag a Window to a New Position.;===============================================;;   IN:    PUSH:WORD - drag flag:;	      bit 15:    1 = bring window to top after drag.;	      bits 8-14: reserved (zero).;	      bits 0-7:  horizontal movement resolution:;		   0 = default grid:;		             4 pixels in 320 mode.;		             8 pixels in 640 mode.;		   1 = every pixel.;		   2 = every 2 pixels.;		   4 = every 4 pixels.;		   8 = every 8 pixels.;		  16 = every 16 pixels.;		  32 = every 32 pixels.;		  64 = every 64 pixels.;		 128 = every 128 pixels.;          PUSH:LONG - starting y,x point in global coordinates.;          PUSH:WORD - grace buffer.;          PUSH:LONG - pointer to bounds RECT.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;DragWindow	PROC;;theWind	equ 9bounds	equ theWind+4grace	equ bounds+4ystart	equ grace+2xstart	equ ystart+2dragFlag	equ xstart+2;;	jsr setup	Get parameters.;;; --- Set default grid -------------------------------------------;	lda dragFlag,s	and #$00FF	bne skip1;	ldx #8	640 grid	ldy #scInfo-1	lda [<data],y	Get current mode.	bmi ok2	ldx #4	320 grid.ok2	txa	ora dragFlag,s	sta dragFlag,s;;; --- Set default drag bounds RECT ------------------------------;skip1	lda bounds,s	Did the caller give	a bounds RECT?	ora bounds+2,s	bne ok3;	jsr deskBounds	wrect = GrayRgn bounds.;	jsr pushwrect	Pass pointer to 'wrect'.	lda dragFlag+4,s	and #$00FF	pha	pea 4	Vertical.	_InsetRect	Make bounds smaller	than desktop.;	tdc	Set address of default bounds RECT.	clc	adc #wrect	sta <workptr	Store pointer to default bounds RECT.	stz <workptr+2;;; --- Set drag bounds -----------------------------------;ok3	lda ystart,s	sta <yrat	lda xstart,s	sta <xrat;	ldy #x2lop1	lda [<workptr],y	Clone bounds RECT.;	pha	Save A.	tyx	Save Y.	txa	Compute index into data area.	clc	adc #slop_bound	tay	pla	sta [<data],y	txy	Restore Y.;	txa	Compute min and max	deltas.	and #3	tax	lda [<workptr],y	sec	sbc <yrat,x;	pha	Save A.	tyx	Save Y.	txa	Compute index into data area.	clc	adc #drag_bound	tay	pla	sta [<data],y	txy	Restore Y.;	dey	dey	bpl lop1;;	jsr pushslop_bound	Pass address of slop_bound.	lda grace+4,s	eor #$FFFF	inc a	pha	pha	_InsetRect	Expand bounds for grace buffer.;;	jsr getwgrect	Get window's global coordinates.;	jsr setwmgrport	Switch to Window Manager's port.	jsr fullport	Set clip to GrayRgn.;	lda dragFlag,s	Special case, window will be top.	bmi ok4	jsr SubStructLoop	Can't drag over windows on top.;ok4	lda dragFlag,s	Pass grid resolution.	and #$00FF	xba	ora #$0010	Min and max deltas in limit RECT.	sta <work;	ldx #wGetDrag	Get address of outline draw routine.	jsr dispatch	sta <work+2	stx <work+4	ora <work+4	Is there a custom draw routine?	beq ok5;	lda <work	Set 'custom draw routine' flag.	ora #$0008	sta <work;ok5	jsr callDrag	Let user reposition	the window.;	sta ystart,s	Save deltay.	txa	sta xstart,s	Save deltax.;;; --- Move window to new position --------------------------;	jsr get_portptr	Get pointer to window's port,	phx	Pass window to SelectWindow.	pha;	lda  xstart,s		;added 3/2/89 by DDG to special case	ora  ystart,s		;..moving by zero	beq  skipMove	ldy #wport+GP_Bounds+x1 Compute new content position.	lda [<wind],y	sec	sbc xstart+4,s	eor #$FFFF	inc a	pha	Pass new x position.	dey	dey	lda [<wind],y	sec	sbc ystart+6,s	eor #$FFFF	inc a	pha	Pass new y position.	lda 7,s	Pass window pointer.	pha	lda 7,s	pha	_MoveWindowskipMove	plx	ply	lda dragFlag,s	Should window be brought foreward?	bpl done;	phy	phx	_SelectWindow;done	jsr restore_port	Restore original port.	jsr fullport	!!!!! Set clip to GrayRgn.;	phb	brl pop16bytes;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;        Check if button is stil down.;150= = = = = = = =	= = = = = = = = = =	= = = = =;;  OUT:    X = FALSE if button still down, TRUE if up.;          Y = Y position of mouse in local.;          A = X position of mouse in local.;tempEvent	equ 1xevent	equ tempEvent+16;	ENTRY ckbuttonckbutton		;       ;	phd	Save current direct	page.;	tsc	Make room for event	record.	sec	sbc #xevent+1	tcs	tcd;	pha	Space for returned flag.	pea 4	Looking for button up event only.	pea 0	Pass pointer to event record.	inc a	pha	_GetNextEvent	plx	Get returned flag.	bne exit150	Was there an up event?;;; --- Button has not come up yet, but double check ----------------------; --- This makes sure that if mouse was already up when got in here; --- that we don't stay here for-ever.;; Changed by mensch and glass 9 apr 89;	lda <tempEvent+modif	and #Btn0State	tax;;; --- Button up event, use position of event -------------------------------;exit150	phx	Save return flag.;	lda #tempEvent+where+y1	jsr pushDpage	_GlobalToLocal	Convert position to	local.;	plx	Restore return flag.;	lda <tempEvent+where+x1	sta <xevent	ldy <tempEvent+where+y1;	tsc	clc	adc #xevent-1	tcs	pla	Get xevent.;	pld	Restore original direct page.;	phx	plx	Return TRUE if button up event.	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;          Check two number's delta.;110= = = = = = = =	= = = = = = = = = =	= = = = = = =;;   IN:    a = one number.;          x = the other number.;;  OUT:    Carry is	set if the two number differ by 5 (plus	or minus 2).;ck_move	stx <work	sbc <work	bpl ok110	eor #$FFFFok110	cmp #5	rts;	ENDP;;;=====================================;        Drag a xor	rectangle.;=====================================;;   IN:    wrect = starting position of	rectangle, in global.;          yrat = cursor's starting y position.;          xrat = cursor's starting x position.;          work = grid and drag flag.;          work+2 =	action proc or custom draw routine.;          drag_bound = bounds RECT.;          slop_bound = grace bounds RECT.;;  OUT:    a = deltay.;          x = deltax.;callDrag	PROC;		;using equates		;using staticRAM;;	pha	Space for result.	pha	pei <work+4	Pass address of action proc or draw.	pei <work+2*** replaced 27-Sep-90 DAL***	pea colorWhite>>16	Drag pattern.***	pea colorWhite	pha	;27-Sep-90 DAL	pha	_Get640Colors	pla	clc	adc #15*32	;offset to color 15	pha*** end of 27-Sep-90 replacement	pei <xrat	Starting position.	pei <yrat	jsr pushwrect	RECT to drag.	jsr pushdrag_bound	Pass pointer to limit RECT.	jsr pushslop_bound	Pass pointer to slop RECT.	pei <work	Drag flag.	_WindDragRect	pla	plx	rts	ENDP;=============================;        Move a window.;=============================;;   IN:    PUSH:WORD - new x content origin in global coordinates.;          PUSH:WORD - new y content origin in global coordinates.;          PUSH:LONG - pointer to window port.;;  OUT:    None.;MoveWindow	PROC;;theWind	equ 10yOrigin	equ theWind+4xOrigin	equ yorigin+2;deltay	equ workdeltax	equ deltay+2;;	jsr setup;	phb	Save current data bank.	phk	Make program and data banks the same.	plb;;; --- If window is full, save current position ---------------;	lda yOrigin,s	tax	lda xOrigin,s	tay	lda #wStartMove	Tell window defProc	move is happening.	jsr callProc2	sta yOrigin,s	txa	sta xOrigin,s;;; --- Set source and destination RECT bounds -----------------;	jsr getwgrect	Get window's starting RECT.;	ldy #blitsrc+x2	Copy Window's bounds into blit's.	jsr copywrect	ldy #blitdes+x2	jsr copywrect;;; --- Compute the window's visible structRgn ---------------;	jsr setwmgrport	Switch to Window Manager's port.;	ldy #wstrucRgn+2	Set wmgr's clip region	jsr pushandle	to the window's StructRgn.	_SetClip;	jsr clipabove	Compute visible area of window.;	           clip = visible region.;	jsr alloc_rgn	jsr alloc_rgn	Allocate region for	destination.;	           rgnptr2 = rgnptr.;	           rgnptr =	new region.	jsr pushclip	jsr pushrgnptr	_CopyRgn rgnptr	= clip (visible window).;	jsr pushclip	jsr pushrgn2	_CopyRgn rgnptr2	= clip (visible window).;;; --- Move the window by changing its Bounds RECT -------------;	lda yorigin,s	Pass new position of content.	tax	lda xorigin,s	jsr pos_wind	Reposition the window.	stx <deltay	Save delta y.	sta <deltax	Save delat x.;	ldy #wstrucRgn+2	Offset window's StructRgn.	jsr offsetrgn;	ldy #wcontRgn+2	Offset window's content region.	jsr offsetrgn;	ldy #wupdateRgn+2	Offset window's update region.	jsr offsetrgn;	jsr testVis	Is the window visible?	bne ok1	brl skip1	If not, no need to redraw.;;; --- Offset the destination region from the source region ------;ok1	jsr pushrgnptr	Pass destination region handle.	pei <deltax	pei <deltay	_OffsetRgn;	jsr pushblitdes	Pass pointer to destination RECT.	pei <deltax	pei <deltay	_OffsetRect	Offset destination RECT.;;; --- Clip blit to not over draw any windows on top of this	one -------;	jsr pushrgnptr	Copy destination region into	jsr pushclip	the clip region (used by clipabove).	_CopyRgn;	jsr clipabove	Subtract any windows on top.;	jsr pushclip	Copy clipped region	back	jsr pushrgnptr	into 'rgnptr'.	_CopyRgn;;; --- BLIT the window to its new home ------------------------;	lda <rgnptr+2	Destination clip region.	ldy #scrn2scrn+PP_Clip+2	sta [<data],y	lda <rgnptr	dey	dey	sta [<data],y;	jsr pushscrn2scrn	_PaintPixels;;;; --- Redraw any part of the window newly exposed -----------;	ldy #wstrucRgn+2	jsr pushandle	Pass window's StructRgn.	jsr pushrgnptr	Pass destination region.	jsr pushrgnptr	Result into 'rgnptr'.	_DiffRgn	rgnptr = StructRgn - Blitted area.;	jsr fullport	Set clip to full screen.	jsr PaintOne	Draw the remainder of the window.;;; --- Redraw whole left by window when moved ----------------;	jsr pushrgn2	Pass where window was.	ldy #wstrucRgn+2	jsr pushandle	Pass where window is.	jsr pushrgnptr	Result in 'rgnptr'.	_DiffRgn	rgnptr = clobbered region.;	jsr paintbehind	Redraw what's in 'rgnptr'.;;; --- Free temp. regions ---------------------------;skip1	jsr disposeRgnPtr;	pei <rgnptr2+2	pei <rgnptr2	_DisposeRgn;;; --- Fix up every window's visRgn ----------------;	jsr calc_vis;	jsr restore_port	Restore original port.;	plb	Restore original data bank.	phb	brl pop8bytes;;; = = = = = = = = =	= = = = = = = =;          Offset region.;100= = = = = = = =	= = = = = = = =;;;   IN:    y = index to region to offset;offsetrgn	jsr pushandle	pei <deltax	pei <deltay	_OffsetRgn	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = =;          Copy 'wrect' into data area.;110= = = = = = = =	= = = = = = = = = =	= = = = = =;;   IN:    y = offset to X2 destination	in data area.;          wrect = RECT to copy.;copywrect	ldx #x2lop110	lda <wrect,x	sta [<data],y	dey	dey	dex	dex	bpl lop110	rts;	ENDP;;;===================================================;          Return the address of DragRect.;===================================================;GetDragRect	PROC;;result	equ 7;;	lda #WindDragRect-1	sta result,s	lda #WindDragRect>>16	sta result+2,s;	lda #0	No error.	clc	rtl;	ENDP;;;====================================;          Drag a rectangle.;====================================;;   IN:    PUSH:LONG - pointer to action procedure routine.;          PUSH:LONG - address of drag pattern.;          PUSH:WORD - x starting point	of mouse, in local.;          PUSH:WORD - y starting point	of mouse, in local.;          PUSH:LONG - pointer to RECT to be dragged, in local.;          PUSH:LONG - pointer to bounds RECT, in local.;          PUSH:LONG - pointer to slop RECT, in local.;          PUSH:WORD - constraining axis:;	    %xxxxxxxxxxxxxx00 - no constraint.;	    %xxxxxxxxxxxxxx01 - Allow only horizontal movement.;	    %xxxxxxxxxxxxxx10 - Allow only vertical movement.;	    %xxxxxxxxxxxxx0xx - Drag RECT.;	    %xxxxxxxxxxxxx1xx - Rubber-band RECT.;	    %xxxxxxxxxxxx0xxx - default drag, action=action proc.;	    %xxxxxxxxxxxx1xxx - Custom RECT, action=draw routine.;	    %xxxxxxxxxxx0xxxx - limit_rect = bounds RECT.;	    %xxxxxxxxxxx1xxxx - limit_rect = min and max values.;	    %xxxxxxxxxx0xxxxx - don't return drag rect in drag_rect.;	    %xxxxxxxxxx1xxxxx - return drag rect in drag_rect.;	    %xxxxxxxxx0xxxxxx - don't bind cursor to limit_rect.;	    %xxxxxxxxx1xxxxxx - bind cursor to limit_rect.;	    %xxxxxxxx0xxxxxxx - don't pass draw flag to custom draw.;	    %xxxxxxxx1xxxxxxx - pass draw flag to custom draw.;	    %00000000xxxxxxxx - grid values, 0,	1, 2, 4, 8, ect...;;  OUT:    LONG - low WORD is delta y, high WORD is delta x.;WindDragRect	PROC EXPORT;		;using equates;VERTAXIS	equ $0001	Set to allow only vertical movement.HORAXIS	equ $0002	Set to allow only horizontal movement.RUBBERBAND	equ $0004	Set if rubber band RECT.CUSTOMRECT	equ $0008	Set if custom RECT draw routine.MMPASSED	equ $0010	Min and Max passed in limit_rect.RETURNDRAG	equ $0020	Return drag RECT in	drag_rect.BOUNDXY	equ $0040	Set to bind cursor to limit_rect.PASSFLAG	equ $0080	Pass draw flag to custom draw routine.;grid_val	equ 1grid_val2	equ grid_val+2grid_msk	equ grid_val2+2min_deltay	equ grid_msk+2min_deltax	equ min_deltay+2max_deltay	equ min_deltax+2max_deltax	equ max_deltay+2trect	equ max_deltax+2drag	equ trect+RECTSIZEypt	equ drag+RECTSIZExpt	equ ypt+2moveFlag	equ xpt+2worksize	equ moveFlag+1;constraint	equ worksize+9	Direction of movement allowed.slop_rect	equ constraint+2	Pointer to RECT that is cursor bounds.limit_rect	equ slop_rect+4	Pointer to RECT that is movement bounds.drag_rect	equ limit_rect+4	Pointer to RECT to drag.starty	equ drag_rect+4	Starting point.startx	equ starty+2drag_patt	equ startx+2	Pattern for xor dragging.action	equ drag_patt+4	Address of routine to call while dragging.deltay	equ action+4	Return values.deltax	equ deltay+2;;	jsl IncBusyFlg	phd;	tsc	sec	sbc #worksize	tcs	tcd;	stz <moveFlag	Set 'draw' flag.	inc <moveFlag;;; --- Clone RECTs into my direct page --------------------------;	ldy #x2lop1	tyx	lda [<drag_rect],y	sta <drag,x	lda [<limit_rect],y	sta <min_deltay,x	dey	dey	bpl lop1;;; --- Set up grid values -------------------------------------;	lda <constraint+1	Get grid value.	and #$00FF	bne store1	inc a	At least one pixel.store1	sta <grid_val	$0001 $0002 $0004 $0008...	sta <grid_val2	lsr <grid_val2	$0000 $0001 $0002 $0004...	dec a	eor #$FFFF	sta <grid_msk	$FFFF $FFFE $FFFC $FFF8...;;; --- Compute min and max deltax -----------------------------;	lda <constraint	Was the min and max	values passed?	and #MMPASSED	bne ok2;	ldx #x1	lda <constraint	Bind the drag RECT or the cursor?	and #BOUNDXY	beq bindRect;;; ------ Bind the cursor to the limit RECT -------------------;; MMPASSED = 0; BOUNDXY  = 1;lop5	lda <min_deltay,x	sec	sbc <starty,x	sta <min_deltay,x;	lda <max_deltay,x	sec	sbc <starty,x	sta <max_deltay,x;	dex	dex	bpl lop5	bra skip3;;; ------ Bind the drag RECT to the limit RECT ----------------;; MMPASSED = 0; BOUNDXY  = 0;bindRect		; lop3	lda <min_deltay,x	sec	sbc <drag+y1,x	sta <min_deltay,x;	lda <max_deltay,x	sec	sbc <drag+y2,x	sta <max_deltay,x;	dex	dex	bpl lop3;;; --- Place deltas on grid -----------------------------------;skip3	lda <grid_msk	Round up minimum up, if needed.	eor #$FFFF	and <min_deltax	beq skip4	Already on grid?;	lda <min_deltax	Round up.	and <grid_msk	clc	adc <grid_val2	adc <grid_val2	sta <min_deltax;skip4	lda <max_deltax	Round down.	and <grid_msk	sta <max_deltax;;; --- Constrain movement -------------------------------------;ok2	ldx #0	lda <constraint	and #VERTAXIS+HORAXIS	beq ok1	Any constrain on?	dec a	Constrain horizontally?	beq con_hor	dec a	bne ok1	inx	Constrain vertically.	inxcon_hor	stz <min_deltay,x	stz <max_deltay,x;;;; --- More initialization ------------------------------------;ok1	stz <deltay	Start with no movement.	stz <deltax;;; --- Set up pen for outline dragging ------------------------;	pei <drag_patt+2	Pass address of xor	pattern.	pei <drag_patt	_SetPenPat		;was PenPat 17-Sep-90 DAL;	pea 2	XOR mode.	_SetPenMode		;was PenMode 17-Sep-90 DAL;	pea 2	pea 1	_SetPenSize;;; --- Drag RECT ----------------------------------------------;lop2	jsr xorbox	Draw XOR box.;lop4	jsr ckbutton	Is button still down?	sty <ypt	sta <xpt	bne done2;;; --- Call action routine ------------------------------------;	lda <constraint	Is there a custom draw routine?	and #CUSTOMRECT	bne skip1;	ldx <action+1	Was an action routine passed?	beq skip1	lda <action	jsl longCall	Call action routine.;;skip1	jsr ckposition	bcc lop2	Redraw?	bra lop4;;; --- Exit ---------------------------------------------------;done2	jsr ckposition	Check position one last time.	bcc skip2	Box already erased?	jsr xorbox	Erase xor box.;skip2	_PenNormal	Reset pen patteren.;	tsc	clc	adc #worksize	tcs;;	phb	brl pop26bytes;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = =;        Check cursor, move RECT if needed.;100= = = = = = = =	= = = = = = = = = =	= = = = = = =;;  OUT:  Carry flag	set if no need to redraw.;ckposition		; ;;; --- Check if cursor is inside 'slop_rect' ------------------;	pha	Space for result.	lda #ypt	Pass pointer to point to check.	jsr pushDpage	pei <slop_rect+2	Pass pointer to RECT to check.	pei <slop_rect	_PtInRect	Is the cursor in slop_rect?	pla	bne ok100;;; ------ Reset RECT	to starting place ------------------------;	lda <starty	sta <ypt	lda <startx	sta <xpt;;; --- Check if there has been any movement -------------------;ok100	jsr getdelta	Did the mouse move?	cmp <deltay	bne moveit100	cpx <deltax	beq ckCustom;moveit100	jsr xorbox	Erase XOR box before move.;	jsr getdelta	Compute and set the	new deltas.	sta <deltay	stx <deltax	clc	Redraw flag.	rts;;ckCustom	lda <constraint	Should the draw routine be called anyway.	and #PASSFLAG	beq exit100;	stz <moveFlag	Clear draw flag.	jsr xorbox	Call custom draw routine.	inc <moveFlag	Set draw flag back to drawing.;exit100	sec	No need to redraw.	rts	Carry set, no need to redraw.;;; = = = = = = = = =	= = = = = = = = =;        Compute delta;110= = = = = = = =	= = = = = = = = =;;   IN:    ypt, xpt	= new point.;          starty, startx = original point.;;  OUT:    a = delta y.;          x = delta x.;getdelta	lda <xpt	Current position,	sec	sbc <startx	less starting position,	tax	equals delta x.;	and <grid_msk	Force delta x to grid.	pha;	txa	Should delta x be rounded?	and <grid_val2	beq ok110;	asl a	Round delta x up.	clc	adc 1,s	sta 1,s;ok110	pla	New delta x.	ldx #x1	jsr bindDelta	tya	and <grid_msk	Force delta x to grid.	pha;	tya	Should delta x be rounded?	and <grid_val2	beq ok111;	asl a	Round delta x up.	clc	adc 1,s	sta 1,s;ok111		; Delta x on stack.;;; --- Compute the y	delta ------------------------------------;	lda <ypt	sec	sbc <starty	New delta y.	ldx #y1	jsr bindDelta	tya	plx	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = =;          Bind delta to limit RECT.;120= = = = = = = =	= = = = = = = = = =	= = = =;;   IN:    a = new delta.;          x = x or	y offset.;bindDelta	ldy <min_deltay,x	jsr find_max	a = max.;	ldy <min_deltay,x	Did the point start	outside limit?	bmi ok120;	sec	sbc <min_deltay,x	bcs ok120;	lda #0;ok120	ldy <max_deltay,x	jsr find_max	New delta x bound to min and max.;	lda <max_deltay,x	bpl ok121;	tya	sec	sbc <max_deltay,x	tay	bmi ok121;	ldy #0;ok121	rts;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =;        Find the greater of two signed	numbers.;130= = = = = = = =	= = = = = = = = = =	= = = = = = = =;;   IN:    a = one signed number.;          y = the other signed number.;;  OUT:    a = the greater of a or y.;          y = the lesser of a or y.;          x = same	as in.;agr_y	equ 1;find_max	phx	Save x.;	phy	Save y.	tax	Save a.	sec	sbc agr_y,s	bvs lab130	bmi dest130	bra exit130lab130	bmi exit130dest130	txy	x = A.	pla	a = X.	plx	rts;exit130	txa	a = A.	ply	x = X.	plx	rts;;; = = = = = = = = =	= = = = = = = = = =;        Draw a XOR	rectangle.;140= = = = = = = =	= = = = = = = = = =;;   IN:    starty =	cursor starting y position.;          startx =	cursor starting x position.;          deltay =	cursor y position to draw at.;          deltax =	cursor x position to draw at.;          drag = starting RECT.;xorbox	lda <constraint	Rubber-band or drag?	and #RUBBERBAND	beq dragit140;;; --- Set RECT for drag or rubber-band -----------------------;	ldx #x1lop140	ldy <drag+y1,x	lda <drag+y2,x	clc	adc <deltay,x;	jsr find_max;	sty <trect+y1,x	sta <trect+y2,x	dex	dex	bpl lop140;	bra draw140;;; ------ Offset the	RECT for dragging ------------------------;dragit140	ldx #x1lop141	lda <drag+y1,x	clc	adc <deltay,x	sta <trect+y1,x;	lda <drag+y2,x	clc	adc <deltay,x	sta <trect+y2,x;	dex	dex	bpl lop141;;; --- Draw the shape -----------------------------------------;draw140	lda <constraint	Return the drag RECT?	and #RETURNDRAG	beq skip140;	ldy #x2	Return the RECT to the caller.lop142	tyx	lda <trect,x	sta [<drag_rect],y	dey	dey	bpl lop142;;skip140	lda <constraint	Custom draw routine?	and #CUSTOMRECT	beq default140;;; ------ Custom RECT drag ------------------------------------;	lda <constraint	Pass draw flag?	and #PASSFLAG	beq skip141;	pei <moveFlag	Pass the movement flag.;skip141	pei <deltax	Pass deltas.	pei <deltay;	ldx <action+1	lda <action	jsl longCall	Call draw routine.	rts;;; ------ Default draw ----------------------------------------;default140	pei <trect+x1	; get into place	pei <trect+y1	_MoveTo;	lda <trect+x2	; draw top	dec a	dec a	pha	pei <trect+y1	_LineTo	pea 0	; move down one	pea 1	_Move;	lda <trect+x2	; draw right	dec a	dec a	pha	lda <trect+y2	dec a	pha	_LineTo	pea -2	; move left two	pea 0	_move;	pei <trect+x1	; draw bottom	lda <trect+y2	dec a	pha	_LineTo;	pea 0	; move up one	pea -1	_Move;	pei <trect+x1	; draw left	lda <trect+y1	inc a	pha	_LineTo	rts;	ENDP;;;==========================================;        Get current mouse position.;==========================================;;  OUT:  yrat = mouse y position.;        xrat = mouse x position.;getratpos	PROC;		;using equates;;	lda #yrat;	ENTRY getratpos2getratpos2		;       ;	jsr pushDpage	_GetMouse	rts	ENDP;;;            APPEND	WACCESS.ASM	TITLE 'Apple IIGS Window Manager                   WACCESS.ASM';;          Copyright Apple Computer, Inc. 1986,1987,1988;          All rights reserved;          Written by Dan Oliver;;;==========================================;          Get/Set global flag.;==========================================;;   IN:    WORD - negative to clear bits, positive to set bits,;                 zero to just return current global flag.;;  OUT:    WORD - global flag after change.;WindowGlobal	PROC;;newState	equ 9newFlag	equ newState+2;;	jsl IncBusyFlg	phd	Save caller's zero page.	tcd;	ldy #WindGlobal;	lda newState,s	Set or reset bits?	bpl setBits;	and [<data],y	bra exit3;setBits	ora [<data],yexit3	sta [<data],y	sta newFlag,s;	phb	brl pop2bytes	ENDP;;;=========================================;          Set the system window flag;          in the window record.;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetSysWindow	PROC;;;	jsr setup;	ldy #wport+4	lda [<wind],y	ora #$8000	Set system window flag.	sta [<wind],y;	phb	brl pop4bytes	ENDP;;;=========================================;          Set updateDraw;=========================================;;   IN:    PUSH:LONG - address of routine to draw window's content region.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetCDraw	PROC;;theWind	equ 9newContDraw	equ theWind+4;;	jsr setup;	ldy #wContDraw;;	ENTRY setWindLongsetWindLong		;       ;	lda newContDraw,s	sta [<wind],y	iny	iny	lda newContDraw+2,s	sta [<wind],y;	phb	brl pop8bytes	ENDP;;;==================================================;          Set application's reserved;          LONG in window record.;==================================================;;   IN:    PUSH:LONG - value to set.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetWRefCon	PROC;;;	jsr setup;	ldy #wRefCon	bra setWindLong	ENDP;;;=============================================;          Set wdefProc in window record.;=============================================;;   IN:    PUSH:LONG - address of new window definition procedure.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetDefProc	PROC;;;theWind	equ 9newDefProc	equ theWind+4;;	jsr setup;	ldy #wDefProc	bra setWindLong	ENDP;;;=====================================================;          Return wdefProc from window record.;=====================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - wdefProc from window's record.;GetDefProc	PROC;;theWindow	equ 9result	equ theWindow+4;;	jsr setup;	ldy #wDefProc	bra get_long	ENDP;;;======================================================;          Return wcontrol from window record.;======================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - wcontrol from window's record.;GetWControls	PROC;;theWindow	equ 9result	equ theWindow+4;;	jsr setup;	ldy #wControls	bra get_long	ENDP;;;==================================================;          Read application's reserved;          LONG in window record.;==================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - application's reserved LONG,;                 set only by NewWindow	and SetWRefCon.;GetWRefCon	PROC Export; Change getWRefCon to not alter workptr. This is due to the listplus application; which calls GetWRefCon in its custom control procedure. Since the control happens to; be in the frame of the window, this was causing many window manager temps to be destroyed; that were not supposed to be destroyed in select window. Future versions of the window; manager should change selectwindow to save and restore needed vars around the call to ; drawentireframe.;; Stack for getWRefCon...oldDPage	equ 1RTL1	equ oldDPage+2RTL2	equ RTL1+3TheWindow	equ RTL2+3Result1	equ TheWindow+4	phd	; save the callers dpage	tsc	; now use the stack as temp dpage	tcd	ldy #wRefCon-4	; offset to refcon (-4 cause this ain't window ptr)	lda [<theWindow],y	; and get the data to return	sta <result1	iny	iny	lda [<theWindow],y	sta <Result1+2; Since pop4Bytes might need something I don't know about at this late hour...	lda RTL1+4	; move the return address	sta RTL1+8	; down by 4 bytes	lda RTL1+2	sta RTL1+6	lda RTL1	sta RTL1+4	pld	; recover the direct page	pla	; strip off 4 bytes	pla	lda #0	; no errors possible	clc	; clear the error flag	rtl	; and go home	EndP;;;; Change getlong to be an internal proc now...; 5/11/89 menschget_long	proc		;       theWind	equ 9result	equ theWind+4;;	lda [<wind],y	sta result,s	iny	iny	lda [<wind],y	sta result+2,s;	phb	brl pop4bytes	ENDP;;;=========================================;          Get uContDraw;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - address of routine to	draw window's content region.;GetCDraw	PROC;;;	jsr setup;	ldy #wContDraw	bra get_long	ENDP;;;====================================================;          Return wframe from window record.;====================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    WORD - wframe from window's record.;GetWFrame	PROC;;theWindow	equ 9result	equ theWindow+4;;	jsr setup;	ldy #wframe	lda [<wind],y	sta result,s;	phb	brl pop4bytes	ENDP;;;========================================================;          Return wstrucRgn from window	record.;========================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - wstrucRgn from window's record.;GetStructRgn	PROC;;;	jsr setup;	ldy #wStrucRgn	bra get_long	ENDP;;;========================================================;          Return wcontRgn from window record.;========================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - wcontRgn from window's record.;GetContRgn	PROC;;;	jsr setup;	ldy #wContRgn	bra get_long	ENDP;;;========================================================;          Return wupdateRgn from window record.;========================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - wupdateRgn from window's record.;GetUpdateRgn	PROC;;;	jsr setup;	ldy #wUpdateRgn	bra get_long	ENDP;;;=================================================;          Return wnext from window record.;=================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - pointer to next window's record.;GetNextWindow	PROC;;theWind	equ 9result	equ theWind+4;;	jsr setup;	ldy #wnext+2	Get pointer to next	window,	lda [<wind],y	tax	dey	dey	lda [<wind],y	jsr get_portp2	convert it to a port pointer,	sta result,s	and return it.	txa	sta result+2,s;	phb	brl pop4bytes	ENDP;;;=========================================;          Return the window type.;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    WORD - not zero if a system window, zero if application window.;GetSysWFlag	PROC;		;using equates;theWindow	equ 9result	equ theWindow+4;;;   OUT:   WORD - negative if a system window, positive if an application's.;	ENTRY GetWKindGetWKind*** added 15-May-91 DAL -- if input pointer is NIL, always return False	pha	lda 7+1+2,s	bne @notNIL	sta 11+2,s	;zero out result word	pla	ldx #0	;no error	ldy #4	;pop 4 bytes	jml $e10184	;ToStrip@notNIL	pla*** end of 15-May-91 DAL	jsr setup;	ldy #wport+4	lda [<wind],y	and #$8000	Get system window flag.	sta result,s	Return state to caller.	phb	brl pop4bytes	ENDP;;;;%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%;%%%			             %%%;%%%   The following Window Manager calls are specific to the window     %%%;%%%   defProc.  The Window Manager hands the call off to the defProc.   %%%;%%%			             %%%;%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%;;;==================================================;          Set application's horizontal;          origin mask.;==================================================;;   IN:    PUSH:WORD - value to set.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetOrgnMask	PROC;;;	jsr setup;	lda #wSetOrgMask	Request number.	jsr callProc;	phb	brl pop6bytes	ENDP;;;=========================================;          Set wmaxheight & wmaxwidth.;=========================================;;   IN:    PUSH:WORD - maximum width of	content allowed when sizing the window.;          PUSH:WORD - maximum height of content allowed when sizing the window.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetMaxGrow	PROC;;;	jsr setup;	lda #wSetMaxGrow	Request number.	bra setCallProc	ENDP;;;=========================================;          Set vscroll & hscroll;=========================================;;   IN:    PUSH:WORD - number of pixels	to scroll when arrowed in right scroll.;          PUSH:WORD - number of pixels	to scroll when arrowed in bottom scroll.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetScroll	PROC;;	jsr setup;	lda #wSetScroll	Request number.	bra setCallProc	ENDP;             ;;=========================================;          Set vpage & hpage.;=========================================;;   IN:    PUSH:WORD - number of pixels	to scroll when paged in right scroll.;          PUSH:WORD - number of pixels	to scroll when paged in bottom scroll.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetPage	PROC;;;	jsr setup;	lda #wSetPage	Request number.	bra setCallProc	ENDP;;;=============================================;          Set wInfoRef  in window record.;=============================================;;   IN:    PUSH:LONG - pointer to text string to appear in information bar.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetInfoRefCon	PROC;;;	jsr setup;	lda #wSetInfoRefCon	Request number.	bra setCallProc	ENDP;;;=============================================;          Set wInfoDraw in window record.;=============================================;;   IN:    PUSH:LONG - address of routine to draw in information bar.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetInfoDraw	PROC;;;	jsr setup;	lda #wSetInfoDraw	Request number.	bra setCallProc	ENDP;;;=========================================;          Set y_origin & x_origin.;=========================================;;   IN:    PUSH:WORD - flag, TRUE to scroll content.;          PUSH:WORD - x origin of content.;          PUSH:WORD - y origin of content.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetCOrigin2	PROC;;;	jsr setup;	lda 1,s	Save caller's direct page.	ldy #callerDpage	sta [<data],y	phb	phb	pla	ldy #callerDataB	sta [<data],y;	lda #wSetOrigin	Request number.	jsr callProc	Call window's defProc.;;	phb	brl pop10bytes	ENDP; ;;=========================================;          Set y_origin & x_origin.;=========================================;;   IN:    PUSH:WORD - x origin of content.;          PUSH:WORD - y origin of content.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetCOrigin	PROC;;theWindow	equ 9newYorigin	equ theWindow+4newXorigin	equ newYorigin+2;;	jsl IncBusyFlg	phd	Save direct page for pop.;	pea 1	Scroll content.	lda newXorigin+2,s	pha	lda newYorigin+4,s	pha	lda theWindow+8,s	pha	lda theWindow+8,s	pha	_SetContentOrigin2;	phb	brl pop8bytes	ENDP;;;=========================================;          Set data_h & data_w.;=========================================;;   IN:    PUSH:WORD - width of data size.;          PUSH:WORD - height of data size.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetDataSize	PROC;;;	jsr setup;	lda #wSetDataSize	Request number.	bra setCallProc	ENDP;;;=============================================;          Set new window full size.;=============================================;;   IN:    PUSH:LONG - pointer to RECT to be replace wFull.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetZoomRect	PROC;;;	jsr setup;	lda #wSetZoomRect	Request number.;	ENTRY setCallProcsetCallProc		;       ;	jsr callProc	Call window's defProc.;	phb	brl pop8bytes		ENDP;;;====================================;        Change a window's title;====================================;;  IN:   LONG - pointer to new title.;        LONG - pointer to window port.;SetWTitle	PROC;;;	jsr setup;	lda #wSetTitle	Request number.	bra setCallProc	ENDP;;;==========================================;        Change frame pattern/colors.;==========================================;;  IN:   LONG - pointer to new color table.;        LONG - pointer to window port.;; OUT:   Nothing.;SetFrameColor	PROC;;theWind	equ 9colorTable	equ theWind+4;;	jsr setup	Put input parameters in zero page.;	lda theWind,s	Set window's color table or system	bne ok1	default color table?	lda theWind+1,s	beq skip1;ok1	lda #wSetColorTable	Request number.	bra setCallProc;;skip1	lda colorTable,s	Use default table?	bne ok2	lda colorTable+2,s	bne ok2;	lda #def_color	Use default color table.	sta colorTable,s	lda #def_color>>16	sta colorTable+2,s;ok2	ldy #defWindClr	New default color table.	lda colorTable,s	sta [<data],y	iny	iny	lda colorTable+2,s	sta [<data],y	phb	brl pop8bytes;	ENDP;;;=============================================;          Set wframe in window record.;=============================================;;   IN:    PUSH:WORD - new wframe for window's record.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SetWFrame	PROC;;;	jsr setup;	lda #wSetFrameFlag	jsr callProc	Call window's defProc.;	phb	brl pop6bytes	ENDP;             ;;=========================================;          Get wmaxheight & wmaxwidth.;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;              ;  OUT:    LONG - high word = max width, low word = max height.;GetMaxGrow	PROC;;theWindow	equ 9result	equ theWindow+4;;	jsr setup;	lda #wGetMaxGrow;	ENTRY getProcLonggetProcLong		;       ;	jsr callProc	Call window's defProc.	sta result,s	txa	sta result+2,s;	phb	brl pop4bytes	ENDP;             ;;=========================================;          Set vscroll & hscroll;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;              ;  OUT:    LONG - high word = number of	pixels scrolled horizontally,;                 low word = number of pixels scrolled vertically.;GetScroll	PROC;;;	jsr setup;	lda #wGetScroll	bra getProcLong	ENDP;             ;;=========================================;          Get vpage & hpage.;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;              ;  OUT:    LONG - high word = number of	pixels paged horizontally,;                 low word = number of pixels paged vertically.;GetPage	PROC;;	jsr setup;	lda #wGetPage	bra getProcLong	ENDP;;;=======================================================;          Return wInfoRef from window record.;=======================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - wInfoRef field in window record.;GetInfoRefCon	PROC;;;	jsr setup;	lda #wGetInfoRefCon	bra getProcLong	ENDP;;;=======================================================;          Return wInfoDraw from window	record.;=======================================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - wInfoDraw from window's record.;GetInfoDraw	PROC;;	jsr setup;	lda #wGetInfoDraw	bra getProcLong	ENDP;;;=========================================;          Get y_origin & x_origin.;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - high word = x origin,	low word = y origin.;GetCOrigin	PROC;;;	jsr setup;	lda #wGetOrigin	bra getProcLong	ENDP;;;=========================================;          Get data_h & data_w.;=========================================;;   IN:    PUSH:LONG - pointer to window's port.;           ;  OUT:    LONG - high word = width of data, low word = height of data area.;GetDataSize	PROC;;;	jsr setup;	lda #wGetDataSize	bra getProcLong	ENDP;;;=============================================;          Return pointer to zoom RECT.;=============================================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    LONG - pointer to wFull in window's record.;GetZoomRect	PROC;;;	jsr setup;	lda #wGetZoomRect	bra getProcLong	ENDP;;;================================================;        Return address of window's title.;================================================;;  IN:   LONG - pointer to window port.;; OUT:   LONG - pointer to title.;GetWTitle	PROC;	jsr setup;	lda #wGetTitle	bra getProcLong	ENDP;;;==========================================;        Return frame pattern/colors.;==========================================;;  IN:     PUSH:LONG - pointer to place	to store color table.;          PUSH:LONG - pointer to window port.;; OUT:     Nothing.;GetFrameColor	PROC;		;using equates;theWind	equ 9desTable	equ theWind+4;;	jsr setup;	lda #wGetColorTable	Ask defProc for color table pointer	jsr callProc	sta <work	Store pointer to color table.	stx <work+2	; Modified 5/10/89 Mensch; Add code here to detect if this is a handle or a pointer.	txa	put high word into <A> to test for handle	bpl @WorkOK	High bit clear, work ok.	ldy #2	else, dereference it in place.	lda [<work],y	tax	lda [<work]	sta <work	stx <work+2;@WorkOK	lda desTable,s	Get pointer to destination table.	sta <work+4	lda desTable+2,s	sta <work+6;	ldy #8	Clone color table into given table.lop1	lda [<work],y	sta [<work+4],y	dey	dey	bpl lop1;	phb	brl pop8bytes	ENDP;;;=============================================;          Return the RECT of a;          window's information bar.;=============================================;;   IN:    PUSH:LONG - pointer to destination RECT for information bar RECT.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;GetRectInfo	PROC;;;	jsr setup;	lda #wGetInfoRect	jsr callProc;	phb	brl pop8bytes	ENDP;;;=======================================================;          Draw the	interior of the info bar.;========================================================;;   IN:    PUSH:LONG - pointer to window port.;;  OUT:    None.;DrawInfoBar	PROC;;;	jsr setup;	lda #wDrawInfo	jsr callProc	Call window's defProc.;exit	phb	brl pop4bytes	ENDP;;;=======================================================;          Set up to draw in information bar.;========================================================;;   IN:    PUSH:LONG - pointer to destination RECT for information bar RECT.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;StartInfoDraw	PROC;;	jsr setup;	lda #wStartInfoDraw	brl setCallProc	Call window's defProc.	ENDP;;;=======================================================;          Reste Window Manager's port;          after StartInfoDrawing call.;========================================================;;   IN:    None.;;  OUT:    None.;EndInfoDrawing	PROC;;	jsl IncBusyFlg	phd	Save original zero page.	tcd	Switch to my zero page.;	lda #wEndInfoDraw	jsr callProc;	phb	brl pop0bytes	ENDP;;;==============================================================;          Call window defProc through generic entry.;==============================================================;;   IN:    a = request number.;	EXPORT callProccallProc	PROC;		;using equates;theWind	equ 11newParam	equ theWind+4;;	pha;	lda newParam+6,s	sta <work	lda newParam+4,s	tay	lda newParam+2,s	tax;	pla;;; = = = = = = = = =	= = = = = = = = = =	= = =;          Call window defProc.; = = = = = = = = =	= = = = = = = = = =	= = =;;   IN:    a = request number.;          x = newParam.;          y = newParam+2;          work = newParam+4;;  OUT:    x/a = returned value from defProc.;	EXPORT callProc2callProc2		;       ;	phy;;; --- Initialize call procedure list -------------------------;	ldy #callProcList	Set request number.	sta [<data],y	iny	iny	lda #0	Set defProc ID.	sta [<data],y	iny	iny	txa	sta [<data],y	Set new parameter.	iny	iny	pla	sta [<data],y	iny	iny	lda <work	sta [<data],y;	jsr pushcallProcList	pla	Pass proc list pointer to defProc.	sta <param	pla	sta <param+2;	ldx #wCallDefProc	Have window defProc	perform operation.	brl dispatch	ENDP;;	      ;            APPEND	WNEW.ASM	TITLE 'Apple IIGS Window Manager                   WNEW.ASM';;          Copyright Apple Computer, Inc. 1986,1987,1988;          All rights reserved;          Written by Dan Oliver;;;;==================================;        Create a New Window.;==================================;;   IN:    PUSH:LONG - space for result.;          PUSH:LONG - pointer to window parameter list.;; OUT:     LONG - pointer to window's port if OK, zero if error.;NewWindow	PROC;		;using equates;param_list	equ 9ret_wind	equ param_list+4;;; --- New parameter	list offsets -----------------------------;paramID	equ 0	ID of parameter list.newDefProc	equ paramID+2	DefProc of window.newData	equ newDefProc+4	Additional data for	new window.;;	jsl IncBusyFlg	phd	Save caller's direct page pointer.	tcd	Switch to my direct	page.;	lda param_list,s	Get pointer to parameter list.	sta <param	lda param_list+2,s	sta <param+2;	lda #0	No window, just in case.	sta ret_wind,s	sta ret_wind+2,s;;; --- Ask defProc for record size ----------------------------;	lda [<param]	What kind of parameter list do I have?	beq ok1;;; ------ Old parameter list ----------------------------------;	ldy #2	Document or Alert window?	lda [<param],y	and #F_ALERT	bne alertProc;	lda #docDefProc	Address of document	defProc.	ldy #docDefProc>>8	bra enter1;alertProc	lda #alertDefProc	Address of alert defProc.	ldy #alertDefProc>>8	bra enter1;;; ------ New parameter list ----------------------------------;ok1	ldy #newDefProc+1	Pass address of custom defProc.	lda [<param],y	pha	dey	lda [<param],y	ply;enter1	sta <workptr	Remember the defProc address.	sty <workptr+1	ldx #wRecSize	Pass operation number.	stz <wind	Pass invalid window	pointer.	stz <wind+2	jsr dispatch2	Ask defProc for extra window record size.	sta <wind	Save possible window record.	stx <wind+2	bcs errorExit1	txy	Should the record even be allocated?	bmi skip1;;; --- Allocate a window record -------------------------------;	clc	Add window record header size	adc #WHEADERSIZE	to addtional size needed by defProc.	sta <work	Remember size.	jsr allocate	Allocate a window record.	sta <wind	Store handle of window record.	stx <wind+2	bcc ok4	Error allocating window?;	ldy #allocateErr	Return error code.errorExit1	phb	brl Epop4bytes	Pop 4 bytes and pass error code.;ok4	ldy #2	Deference handle.	lda [<wind],y	tay	lda [<wind]	sta <wind	Pointer to window record.	sty <wind+2;;; --- Zero the window record -----------------------;	lda <work	Get size of record.	and #$FFFE	Make sure it's even.	tay	lda #0	bra enter3lop3	sta [<wind],yenter3	dey	dey	bpl lop3;	ldy #wframe	Set flag to show record was allocated.	lda #F_ALLOCATE	sta [<wind],yskip1;;; --- Open graf port for window ------------------------------;	lda <wind+2	and #$7FFF	sta <wind+2;	jsr save_port	Save current port.;	jsr get_portptr	Compute where in record port goes.	phx	pha	_OpenPort	bcc ok5	Error opening port?;	tay	Place error code in	y.errorExit2	phy	Save error code.	jsr restore_port	Restore original port.	ply	Return error code in Y.	phb	brl Epop4bytes	Pop 4 bytes and pass error code.;;; --- Set window's defProc -----------------------------------;ok5	ldy #wDefProc	lda <workptr	sta [<wind],y	iny	lda <workptr+1	sta [<wind],y;;; --- Ask the defProc for the window port size and position	--;	ldx #wPosition	Pass operation number.	jsr dispatch	bcs errorExit2;	sta <workptr	Store pointer to position RECT.	stx <workptr+2	ldy #x2	Move position RECT into 'wrect'.lop2	lda [<workptr],y	tyx	sta <wrect,x	dey	dey	bpl lop2;;; --- Set the width	and height of the window (and put content RECT into wrect).;	lda <wrect+x2	Compute window's width.	sec	sbc <wrect+x1	pha	Pass width.	lda <wrect+y2	Compute window's height.	sec	sbc <wrect+y1	pha	Pass height.	_SetPortSize	Set size of window's port.;;; --- Position Bounds RECT so window will be in the correct	position ----;	pei <wrect+x1	pei <wrect+y1	_MovePortTo;	jsr zeroOrigin	SetOrigin( 0,0,).;;; --- Allocate regions for window -----------------------;	ldy #wstrucRgn	First region in record.lop5	phy	Save.;	pha	Return space for region handle.	pha	_NewRgn	Allocate an empty region.;	pla	plx	ply	sta [<wind],y	Store the region handle in the window.	iny	iny	txa	sta [<wind],y	iny	iny	cpy #wstrucRgn+12	All 3 regions allocated?	bne lop5;;; --- Let window initialize anything else -----------;	jsr moveWMgrOnWind	Move Window Manager's port on window.;	ldx #wNew	Initialize flag.	jsr dispatch	Pass message to window.;	jsr getWMgrCtls	Move control list into window and;	                  call moveWmgrBack.;;; --- Draw new Window ---------------------;; ------- Will new window cause the current top window to go under? ----;	ldy #wframe	Start as unhilited.	lda [<wind],y	and #_F_HILITED	sta [<wind],y;	ldx #wBehind	jsr dispatch	sta <workptr	workptr = where to send new window.	stx <workptr+2;	jsr testVis	Test the window's F_VIS flag.	bne ok3	Is the new window visible?;	ldy #wport+GP_VisRgn+2 Set window's VisRgn to empty.	jsr pushandle	_SetEmptyRgn	bra skip2;ok3	lda #$FFFF	cmp <workptr	bne skip2	cmp <workptr+2	bne skip2;	jsr find_top	Find the top most visible window.	beq skip2	Is there a top?;;; ----------- Unhilite top most window -----------------------------------;	pei <workptr+2	Save behind parameter.	pei <workptr	pei <wind+2	Save window pointer.	pei <wind;	sta <wind	Put pointer to top most visible window	stx <wind+2	into 'wind'.;	ldy #WindGlobal	Is unhiliting turned off?	lda [<data],y	bne skip3;	ldy #wstrucRgn+2	Pass handle window's StructRgn.	jsr pushandle	jsr pushGray	Pass handle of desktop.	jsr pushclip	Pass clip region handle.	_SectRgn	Set clip to window and desktop.;	jsr unhilite	Inactivate top window.	jsr deactivate	Send deactivate message to window.	jsr drawframe	Draw inactivated window.;skip3	pla	Restore new window pointer.	sta <wind	pla	sta <wind+2	pla	sta <workptr	pla	sta <workptr+2;;skip2	jsr fullport	Set clip to full desktop.;	lda <workPtr	ora <workPtr+2	bne ok2;	dec <workPtr+2	Make $FFFF	dec <workPtr	dec <workPtr	Make $FFFE to send behind all others.;ok2	jsr fixworkptr	Make workptr a window pointer if plus.	jsr intolist	Put window into list.;	jsr find_top	Find the top most visible window.	cmp <wind	Is the new window top?	bne skip4	cpx <wind+2	bne skip4;	jsr hilite	Hilite new window.	jsr activate	Send activate message to window.;;; --- Compute visible content regions for every window --------;skip4	jsr calc_vis;;; --- Draw new window -----------------------------------------;	jsr alloc_rgn	Allocate a work region.;	ldy #wstrucRgn+2	jsr pushandle	jsr pushrgnptr	_CopyRgn	Draw the whole window.;	jsr PaintOne	Draw the window.;	jsr disposeRgnPtr	Free work region.;;; --- Return pointer to window ------------;	jsr get_portptr	Get pointer to window's port.	sta ret_wind,s	txa	sta ret_wind+2,s;	jsr restore_port	Restore original port.	jsr restore_port	Restore original port.;	phb	brl pop4bytes	ENDP;;;=======================================================================;          Move control list into window and call moveWMgrBack.;=======================================================================;getWMgrCtls	PROC;;;	ldy #wmgr_wind+wControls Move any created controls into	lda [<data],y	the window's wFrameCtls field.	tax	iny	iny	lda [<data],y	ldy #wFrameCtls+2	sta [<wind],y	dey	dey	txa	sta [<wind],y;	brl moveWMgrBack	Back Window Manager	port back to global.	ENDP;;;==============================;        Close a Window;==============================;; IN:    LONG - pointer to window port to close.;OUT:    x = 0 if error, else 1.;CloseWindow	PROC	import KillAuxInfoRecord		;using equates	jsr setup	Get address of theWind.;	stz <param	No additional parameter send to defProc.	stz <param+2	ldx #wDispose	Tell defProc to do additional disposal.	jsr dispatch	tax	Does defProc want to abort close?	beq @1	phb	brl pop4bytes@1;;	jsr setwmgrport	Switch to Window Manager's port.;	jsr erasewind	Take window out of list.;*** Kill the auxiliary info record, if any (added 21-Jan-91 DAL)	lda 9+2,s	pha	lda 9+2,s	pha	;copy of the window pointer passed in	jsl KillAuxInfoRecord*** end of 21-Jan-91 addition	jsr pullparam	Get window pointer again.;;; --- Deallocate any controls in the window ---------------;	jsr get_portptr	Get window's port pointer.	phx	Pass pointer to window's port.	pha	_KillControls	Deallocate all controls in window.	bcc ok1	Is the Control Manager installed?	pla	pla	bra skip1;ok1	ldy #wFrameCtls+2	wControls = wFrameCtls.	lda [<wind],y	tax	dey	dey	lda [<wind],y;	ldy #wControls	sta [<wind],y	iny	iny	txa	sta [<wind],y;	jsr get_portptr	Get window's port pointer.	phx	Pass pointer to window's port.	pha	_KillControls	Deallocate all frame controls in window.;;; --- Remove any activate or deactivate	events for the window being closed ---;skip1	jsr get_portptr	Get window's port pointer.	cmp <CurActive	Does the window have an activate waiting?	bne checkDeact	cpx <CurActive+2	bne checkDeact;	stz <FlgActive	Remove the activate	flag.;checkDeact	cmp <CurDeActive	Does the window have a deactivate waiting?	bne skip2	cpx <CurDeActive+2	bne skip2;	stz <FlgDeActive	Remove the deactivate flag.;;; --- Deallocate memory used by the window's record. ------;skip2	phx	Pass to port pointer.	pha	_ClosePort	Close window's port.;	ldy #wframe	Was the window allocated by me?	lda [<wind],y	and #F_ALLOCATE	beq JoinTheExitCode;	bne @2;	phb;	brl pop4bytes	Done if not allocated.;@2;	pha	Space for returned handle.	pha	pei <wind+2	Convert pointer to handle.	pei <wind	_FindHandle	_DisposeHandle	Free block allocated for window record.;JoinTheExitCode	jsr restore_port	Restore original port.;	phb	brl pop4bytes	ENDP;;===============================================;        Erase a window from the screen.;===============================================;;   IN:    wind = window to be erased and taken out of the list.;*** 26 Apr 89	David Good** If the windGlobal flag said to NOT change the hilighting on windows,* CloseWindow used to skip drawing. Now it just skips the hilighting,* but it still draws the frame.*****************************************************************erasewind	PROC;---------------------------------------------------------------	jsr  testVis		;if the window we are closing is invisible	bne  doVis		;..then do it the slow way	jsr  killAllPortRgns	;dispose of all the regions in the window	brl  outoflist		;..we are killing and take the window out;---------------------------------------------------------------doVis	jsr  alloc_rgn		;allocate a temporary region	ldy  #wstrucRgn+2		;combine the structure region of the	jsr  pushandle		;..window we are closing with the desktop	jsr  pushGray		;..and leave it in our temporary region	pei  <rgnptr+2	pei  <rgnptr	_SectRgn	lda  <topwind		;subtract the structure regions of all	ldx  <topwind+2		;..the windows above the current one	bra  @enterLoop		;..from the temporary region@loop	ldy  #wframe		;if the window is invisible, then don't	lda  [<work],y		;..subtract it.	and  #F_VIS	beq  @nextWindow	pei  <rgnptr+2		;do the subtract	pei  <rgnptr	ldy  #wstrucRgn+2	lda  [<work],y	pha	dey	dey	lda  [<work],y	pha	pei  <rgnptr+2	pei  <rgnptr	_DiffRgn@nextWindow	ldy  #2		;move to the next window	lda  [<work],y	tax	lda  [<work]@enterLoop	stax <work	cmp  <wind		;are we at the topmost window ? If so,	bne  @loop		;..then we are done	cpx  <wind+2	bne  @loop	jsr  fullport		;set the clip region to the full desktop;---------------------------------------------------------------findNewTop	jsr  killAllPortRgns	;dispose of all the regions in the window	ldy  #2		;index for the high word of wNext	lda  [<wind],y		;save the pointer to the next window on	pha		;..the stack	lda  [<wind]	pha	jsr  outoflist		;take the window out of the list	jsr  find_top		;find the topmost visible window. If	beq  @skipDraw		;..there aren't any then skip the hilite	stax <wind	ldy  #WindGlobal		;hiliting off?	lda  [<data],y	bne  @skipHilite	ldy  #wframe		;if the window is already hilited then	lda  [<wind],y		;..skip the hilite	and  #F_HILITED	bne  @skipHilite	lda  [<wind],y	ora  #F_HILITED	sta  [<wind],y	jsr  activate		;send a activate message to the window@skipHilite	jsr  drawEntireFrame	;otherwise draw the entire frame@skipDraw;---------------------------------------------------------------drawAllWindows	pla	sta  <wind	pla	sta  <wind+2@loop	lda  <wind	ora  <wind+2	beql addToDeskRgn	jsr  testVis		;if the window is invisible, then skip	beql @nextWindow		;..it	pei  <rgnptr+2		;see if this window should be drawn by	pei  <rgnptr		;..finding the intersection of the clip	ldy  #wstrucRgn+2		;..and the structure region	jsr  pushandle	jsr  pushclip	_SectRgn	jsr  testclip		;is the clip region NOT empty ? if yes,	bnel @nextWindow		;..then skip drawing	lda  <wind		;is this window the new topmost window ?	cmp  <top_vis		;..If so, then we have already drawn it	bne  @notTheTop		;..so skip just the draw step	lda  <wind+2	cmp  <top_vis+2	beq  @skipDraw@notTheTop	jsr  drawEntireFrame	;draw the new window clipped to our region@skipDraw	ldy  #wContRgn+2		;the new area to update is the intersection	jsr  pushandle		;..of the content region and our clip	jsr  pushclip		;..region. Put it back into the clip	jsr  pushclip		;..region for now.	_SectRgn	jsr  pushclip		;erase the new update area	ldax <wind	clc	adc  #wport+GP_BkPat	bcc  @1	inx@1	phx	pha	_FillRgn	jsr  pushclip		;add the new update area to the update	ldy  #wUpdateRgn+2		;..region	jsr  pushandle	ldy  #wUpdateRgn+2	jsr  pushandle	_UnionRgn	ldy  #port+GP_ClipRgn+2	;offset the new update area to local	lda  [<data],y		;..coordinates, so we can add it to the	tax		;..visible region	dey	dey	lda  [<data],y	jsr  offsetToLocal	jsr  pushclip		;add the new update area to the visible	ldy  #wport+GP_VisRgn+2	;..region also	jsr  pushandle	ldy  #wport+GP_VisRgn+2	jsr  pushandle	_UnionRgn	pei  <rgnptr+2		;subtract the struct region from our temp	pei  <rgnptr		;..so the next window will be clipped	ldy  #wStrucRgn+2		;..properly.	jsr  pushandle	pei  <rgnptr+2	pei  <rgnptr	_DiffRgn@nextWindow	ldy  #2		;move to the next window	lda  [<wind],y	tax	lda  [<wind]	stax <wind	brl  @loop;---------------------------------------------------------------addToDeskRgn	lda  <FloorRgn+1		;if there isn't a floor region then don't	beq  @skipFloor		;..change it !	pei  <FloorRgn+2		;add whatever is left to the floor region	pei  <FloorRgn	jsr  pushrgnptr	pei  <FloorRgn+2	pei  <FloorRgn	_UnionRgn@skipFloor	pei  <rgnptr+2		;clip to our remaining region	pei  <rgnptr	jsr  pushclip	_CopyRgn	jsr  disposeRgnPtr		;free the temporary work region	jsr  PaintDesk		;paint the desktop using cliprgn	jsr  fullport		;set the clip back to a full port	rts;---------------------------------------------------------------;---------------------------------------------------------------killAllPortRgns	ldy  #wport+GP_VisRgn+2	;clear the vis rgn of the killed window	jsr  pushandle	_SetEmptyRgn	ldy  #wUpdateRgn+2		;dispose of all the regions in the window	jsr  @killTheRgn		;..we are killing	ldy  #wContRgn+2	jsr  @killTheRgn	ldy  #wStrucRgn+2@killTheRgn	jsr  pushandle	_DisposeRgn	rts;---------------------------------------------------------------	ENDP****************************************************************;;;==========================================;          Change a	window's size.;==========================================;;   IN:    PUSH:WORD - new content region width.;          PUSH:WORD - new content region height, if both zero, just exit.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;SizeWindow	PROCtheWindow	equ 9newHeight	equ theWindow+4newWidth	equ newHeight+2updateFlag	equ newWidth+2;;	jsr setup;	lda newWidth,s	ora newHeight,s	Are both width and height zero?	beq exit	If yes, just exit.;;; --- Force height and width to be at least one --------------------------;	lda newWidth,s	bne ok4	inc a	sta newWidth,s;ok4	lda newHeight,s	bne ok5	inc a	sta newHeight,s;;; --- Check if there is no change ----------------------------------------;ok5	jsr getcontwh	Compute width/height of content region.;	lda <wrect+y2	cmp newHeight,s	Change in height?	bne ok1	lda <wrect+x2	Change in width?	cmp newWidth,s	beq exit	If no change, I'm done (nothing to do).;;; --- Tell window's defProc about new size -------------------;ok1	ldy #0	Pass address of newHeight and newWidth.	tsc	clc	adc #newHeight	tax	lda #wNewSize	Pass command.	jsr callProc2	Call window's defProc.	sta <uncovered;;; --- Compute new content size -------------------------------;	lda <wrect+y1	sta <rect+y1	clc	adc newHeight,s	sta <rect+y2;	lda <wrect+x1	sta <rect+x1	clc	adc newWidth,s	sta <rect+x2;;; --- Resize window	------------------------------------------;	jsr sizeguts	Resize window, makes content = rect.;exit	phb	brl pop8bytes	ENDP;;;===============================================;          Resize and position a window.;===============================================;;   IN:    PUSH:WORD - TRUE to only draw what's uncovered,;	   FALSE to redraw entire content region.;          PUSH:LONG - pointer to new content RECT in global.;          PUSH:LONG - pointer to window's port.;;  OUT:    None.;ResizeWindow	PROC;;theWindow	equ 9newRect	equ theWindow+4redrawFlag	equ newRect+4;srcRect	equ work;;	jsr setup;;	lda newRect,s	Get pointer to new RECT.	sta <srcRect	lda newRect+2,s	sta <srcRect+2;	ldy #x2	Clone new RECT.lop1	lda [<srcRect],y	tyx	sta <rect,x	dey	dey	bpl lop1;	lda redrawFlag,s	Pass redraw flag.	sta <uncovered;	jsr sizeguts	Resize window, makes content = rect.;	phb	brl pop10bytes	ENDP;;;============================================;          Change a	window's size.;============================================;;   IN:    <wind = pointer to window to	be sized.;          <rect = new size and position of content region.;          <uncovered = FALSE if whole content should be redrawn,;	    TRUE if original content should not	be redrawn.;;  OUT:    <rect = trashed.;          <wrect =	trashed.;;; Change History;; 04 Nov 88	Steven Glass;; Notifies controls of size change.;sizeguts	PROC;		;using equates;;; --- Remember window's current strucRgn ----------------;	jsr alloc_rgn	Get a temp region.;	lda <uncovered	Just whats uncovered?	beq skip1;	ldy #wcontRgn+2	Save the original content region.	jsr pushandle	jsr pushrgnptr	_CopyRgn	rgnptr = content region before resize.	jsr alloc_rgn	rgnptr2 = rgnptr.;;skip1	ldy #wstrucRgn+2	jsr pushandle	jsr pushrgnptr	_CopyRgn	rgnptr = wstrucRgn.;	jsr new_size	content is set to 'rect'.;;; --- Compute new wsturcRgn and wcontRgn ---------------------;	jsr moveWMgrOnWind	Move Window Manager's port on window.	ldx #wCalcRgns	jsr dispatch	Trash 'rect' and 'wrect'.	jsr getWMgrCtls	Move control list into window and;	                  call moveWmgrBack.;; --- Draw anything	uncovered by size change ------------------;	jsr setwmgrport	Current port = Window Manager's,;	jsr testVis	Is the window visible?	beq skip4	If not, no need to draw anything.;	jsr calc_vis;          	jsr pushrgnptr	From the hole,	ldy #wstrucRgn+2	add the new window,	jsr pushandle	jsr pushrgnptr	and that's the clobbered region.	_UnionRgn;;; --- Subtract any windows above ----------------------------------;	jsr pushclip	Save current clip handle.;	lda <rgnptr	Replace clip handle	with	ldy #port+GP_ClipRgn region to subtract	from.	sta [<data],y	lda <rgnptr+2	iny	iny	sta [<data],y;	jsr SubStructLoop	Subtract windows above.;	pla	Restore clip handle.	ldy #port+GP_ClipRgn	sta [<data],y	pla	iny	iny	sta [<data],y;;	lda <uncovered	Just whats uncovered?	beq skip2;	jsr pushrgn2	Intersect old content,	ldy #wcontRgn+2	and new content region.	jsr pushandle	jsr pushrgn2	_SectRgn;	jsr pushrgnptr	Clobbered region,	jsr pushrgn2	less common area of	old and new content,	jsr pushrgnptr	equals new clobbered region.	_DiffRgn	rgnptr = rgnptr - rgnptr2;;skip2	ldx #GrayRgn	jsr pushptr	jsr pushrgnptr	jsr pushrgnptr	_SectRgn	Clip clobbered region to desktop.;;	jsr paintonedown	Redraw clobbered area.;skip4	jsr disposeRgnPtr	Free temp region;;	lda <uncovered	Just whats uncovered?	beq skip3;	jsr pushrgn2	Free copy of original content region.	_DisposeRgn;	stz <uncovered	Reset default redraw global flag.;;skip3	;; Notify the controls in this window about the change in size.; (added 04 Nov 88 SEG);	PushWord #FctlTellAboutSize	PushWord #ctlWindChangeSize	PushLong #0	jsr get_PortPtr	phx	pha	_NotifyCtls	brl restore_port	Restore original port.	ENDP;;;=====================================================;          Set a window's size and position.;=====================================================;;   IN:    rect = new size and position.;          wind = window pointer.;;  OUT:    window's port changed.;new_size	PROC;		;using equates;;	jsr save_port	Save original port.;	jsr get_portptr	phx	pha	_SetPort	Switch to window's port.;	lda <rect+x2	sec	sbc <rect+x1	pha	Pass new width.	lda <rect+y2	sec	sbc <rect+y1	pha	Pass new height.	_SetPortSize;	ldx <rect+y1	Global Y position.	lda <rect+x1	Global X position.	jsr pos_wind	Position the window.;	brl restore_port	ENDP;;;===============================================;        Offset a window's Bounds RECT.;        Used to position a window.;===============================================;;   IN:  x = global	y position of content.;        a = global	x position of content.;        wind = window to reposition.;;  OUT:  x = deltay.;        a = deltax.;pos_wind	PROC;		;using equates;deltay	equ 1deltax	equ deltay+2;;	eor #$FFFF	Negate x position.	inc a	pha	Save.;	txa	eor #$FFFF	Negate y position.	inc a	pha	Save.;;	ldy #wport+GP_Bounds+x1 Compute delta x.	lda [<wind],y	sec	sbc deltax,s	sta deltax,s;	dey	Compute delta y.	dey	lda [<wind],y	sec	sbc deltay,s	sta deltay,s;;lop1	lda [<wind],y	Offset bounds RECT.	sec	sbc deltay,s	sta [<wind],y;	iny	iny	lda [<wind],y	sec	sbc deltax,s	sta [<wind],y;	iny	iny	cpy #wport+GP_Bounds+x2 Done?	bcc lop1;;	plx	Return deltay.	pla	Return deltax.	rts	ENDP;=====================================;          Track grow region.;=====================================;;   IN:    PUSH:WORD - minimum horizontal position.;          PUSH:WORD - minimum vertical	position.;          PUSH:WORD - x starting position.;          PUSH:WORD - y starting position.;          PUSH:LONG - pointer to window's port.;;  OUT:    LONG - low word is content's new height,;                 high word is content's new width.;GrowWindow	PROCtheWindow	equ 9ystart	equ theWindow+4xstart	equ ystart+2min_h	equ xstart+2min_w	equ min_h+2new_h	equ min_w+2new_w	equ new_h+2;content_h	equ work+8content_w	equ content_h+2;;*** added 26-Nov-90 DAL	pha	pha	;space for GetWFrame result	lda 9+4,s	pha	lda 7+6,s	pha	_GetWFrame	pla	sta >gwTheFrame	pha	pha	lda 9+6,s	;window pointer, high word	pha	sta >gwTheWindow+2	lda 7+8,s	;window pointer, low word	pha	sta >gwTheWindow	_GetZoomRect	pushlong #oldZoomRect	pea 0	pea 8	_BlockMove	pla*** end of 26-Nov-90 DAL	jsr setup	lda #wStartGrow	Tell window's defProc starting to grow.	jsr callProc2;	jsr setwmgrport	Switch to Window Manager's port.	jsr fullport;	ldy #wcontRgn	Get global coordinates of content.	jsr getbounds	wrect = content bounds.	jsr wrect2rect	rect = wrect.;	ldy #wstrucRgn	Get global coordinates of content.	jsr getbounds	wrect = wwStructRgn	bounds.;;; --- Compute min and max deltas -------------------------------------------;	lda <rect+y2	Compute the height of the content area.	sec	sbc <rect+y1	inc a	sta <content_h;	lda <rect+x2	Compute the width of the content area.	sec	sbc <rect+x1	inc a	sta <content_w;	lda min_h,s	sec	sbc <content_h	ldy #drag_bound+y1	Min y delta.	sta [<data],y;	lda min_w,s	sec	sbc <content_w	ldy #drag_bound+x1	Min x delta.	sta [<data],y;	lda #wGetMaxGrow	Pass request number.	jsr callProc2	a = max height.;	                  x	= max width.;	sec	sbc <content_h	ldy #drag_bound+y2	Max y delta.	sta [<data],y;	txa	sec	sbc <content_w	ldy #drag_bound+x2	Max x delta.	sta [<data],y;;; --- Set slop bounds ------------------------------------------------;	ldy #scInfo+8+x2	ldx #slop_bound+x2lop1	lda [<data],y	phy	txy	sta [<data],y	ply	dey	dey	dex	dex	cpx #slop_bound	bcs lop1;;; --- Call DragRect	---------------------------------------------------;	lda xstart,s	Pass cursor's starting position.	sta <xrat	lda ystart,s	sta <yrat;	lda #$013C	Custom draw, on one	pixel grid.	sta <work;	lda #draw_grow>>16	Address of custom draw routine.	sta <work+4	lda #draw_grow	sta <work+2;	jsr callDrag	Drag the grow box.;	                  a	= delta y.;	                  x	= delta x.;;; --- Compute new width and height ---------------------------------;	tay	Any change?	bne ok3	txy	beq store3	Return zero if no change.;ok3	clc	Compute new content	height.	adc <content_h	dec a	tay;	txa	Compute new content	width.	clc	adc <content_w	dec a;store3	sta new_w,s	Return new content size to caller.	tya	sta new_h,s;;; --- Clean-up and exit -----------------------------------------;	jsr restore_port	Restore original port.;;	stz <uncovered	Global flag.	inc <uncovered	Don't redraw original content region.*** added 26-Nov-90 DAL	lda new_w,s	ora new_h,s	bne @changedSize	pushlong #oldZoomRect	lda >gwTheWindow+2	pha	lda >gwTheWindow	pha	_SetZoomRect	lda >gwTheFrame	pha	lda >gwTheWindow+2	pha	lda >gwTheWindow	pha	_SetWFrame@changedSize*** end of 26-Nov-90 DAL	phb	brl pop12bytesoldZoomRect	ds.b 8	;26-Nov-90 DALgwTheWindow	dc.l 0	;26-Nov-90 DALgwTheFrame	dc.w 0	;26-Nov-90 DAL;; = = = = = = = = =	= = = = = = = = = =	= = =;          Custom DragRect outline;          draw routine.; = = = = = = = = =	= = = = = = = = = =	= = =;draw_grow;deltay	equ 6deltax	equ deltay+2;;	phd	Save caller's direct page.;	pha	Space for result.	pha	pea 0	Pass system tool flag.	pea WindToolNum	Pass Window Manager	tool number.	_GetWAP	pld	Window Manager's direct page pointer.	pla	Don't need high word.;	stz <param	Pass address of window frame RECT.	tdc	clc	adc #wrect	sta <param+2;	ldx #wGrowFrame	Ask defProc to draw	outline.	jsr dispatch	Pass message to window's defProc.	tax	Did defProc complete task?	bne exit10;;; --- Draw default grow outline ----------------------------------------;;   IN:    wrect = window frame RECT.;          rect = content RECT.;	jsr pushwrect	Push the address of	'wrect'.	_FrameRect;	lda <rect+y1	sta <work+y1	lda <rect+x1	sta <work+x1;	lda <rect+y2	clc	adc deltay,s	sta <work+y2;	lda <rect+x2	clc	adc deltax,s	sta <work+x2;	jsr pushwork	_FrameRect;;exit10	pld	Restore caller's direct page.;	lda 0,s	Move return address	down stack.	sta 4,s	lda 2,s	sta 6,s	pla	Remove input parameters.	pla	rtl;	ENDP;;;============================================;          Pin a point in a RECT.;============================================;;   IN:    PUSH:WORD - x coordinate of point to pin.;          PUSH:WORD - y coordinate of point to pin.;          PUSH:LONG - pointer to RECT in which to pin point.;;  OUT:    LONG - high word is pinned y	coordinate,;                 low word is pinned x coordinate.;PinRect	PROC;		;using equates;bindRect	equ 9ypoint	equ bindRect+4xpoint	equ ypoint+2ypinned	equ xpoint+2xpinned	equ ypinned+2;;	jsl IncBusyFlg	phd	Save orginal zero page.;	tsc	Switch zero page into stack.	tcd;; Zero out the result	lda <yPoint	sta <yPinned	lda <xPoint	sta <xPinned	; now test to see the Y value first...	lda <yPoint	; test to see if this is greaterthan or equal to	cmp [<bindRect]	bpl @1	; if this test is ok, then <yPoint is greater than bind.y1	lda [<bindRect]	sta <yPinned	bra @testX	; now tets the <X> value@1	ldy #4	cmp [<bindRect],y	bmi @testX	; <Y> value is fine...	lda [<bindRect],y	dec a	sta <yPinned; and test the X value@testX	ldy #2	lda <xPoint	; test to see if this is greaterthan or equal to	cmp [<bindRect],y	bpl @2	; if this test is ok, then <yPoint is greater than bind.y1	lda [<bindRect],y	sta <xPinned	bra @TestDone	; now tets the <X> value@2	ldy #6	cmp [<bindRect],y	bmi @testDone	; <Y> value is fine...	lda [<bindRect],y	dec a	sta <xPinned@TestDone	phb	brl pop8bytes	ENDP;; Was:;;; --- Force negative top and left to zero ------------;;	lda [<bindRect];	bpl ok1;	lda #0;ok1	sta <ypinned;;;	ldy #x1;	lda [<bindRect],y;	bpl ok2;	lda #0;ok2	sta <xpinned;;;;;; --- Pin the point	--------------------------------------------;;;	lda <ypoint;	cmp <ypinned;	bcs skip1;	lda <ypinned	Pin to top side.;;;skip1	iny;	iny;	cmp [<bindRect],y;	bcc store1;	lda [<bindRect],y	Pin to bottom side,;	dec a	less one.;store1	sta <ypinned;;;;;	lda <xpoint;	cmp <xpinned;	bcs skip2;	lda <xpinned	Pin to left side.;;;skip2	iny;	iny;	cmp [<bindRect],y;	bcc store2;	lda [<bindRect],y	Pin to right side,;	dec a	less one.;store2	sta <xpinned;;;;;	phb;	brl pop8bytes;	ENDP;;=================================================;          Flip a window's zoom position.;=================================================;;   IN:    PUSH:LONG - pointer of window's port.;;  OUT:    None.;ZoomWindow	PROC;;;	jsr setup;	lda #wZoomWindow	Request number.	jsr callProc2	Tell defProc to Zoom Window.;	phb	brl pop4bytes	ENDP;;;            APPEND	WFIND.ASM	TITLE 'Apple IIGS Window Manager               WFIND.ASM';;          Copyright Apple Computer, Inc. 1986,1987,1988;          All rights reserved;          Written by Dan Oliver;;;=====================================;        Find Window Function.;=====================================;;  IN:   PUSH - LONG - address of where	to store window pointer.;        PUSH - LONG - point on screen of where to check.;; OUT:   WORD - function at given point, window also set at	given address.;;               wInDesk         On Desktop.;               wInMenuBar      On System Menu Bar.;               wInSysWindow    On System window.;               wInContent      In content region.;               wInDrag         In drag	region.;               wInGrow         In grow	region, active window only.;               wInGoAway       In go-away region, active window only.;               wInZoom         In zoom	region, active window only.;               wInInfo         In information bar.;               wInVScroll      In right scroll bar.;               wInHScroll      In bottom scroll bar.;               wInFrame        In frame, but not on anything else.;;FindWindow	PROC;		;using equates;point	equ 9	Point to check.retWind	equ point+4	Address of where to	store window.retLoc	equ retWind+4	Location on stack of return parameter.;;	jsl IncBusyFlg	phd	tcd*** added 25-Mar-91 DAL	stz <wind+2	stz <wind*** end of 25-Mar-91 DAL;	jsr fullport	Set clip to GrayRgn.;;; --- Check if point is on the desktop ----------------------------;	pha	Space for return value.	pea 0	Pass pointer to point to check.	tsc	clc	adc #point+4	pha	pei <GrayRgn+2	Region to check, desktop.	pei <GrayRgn	_PtInRgn	Check if the point is on the desktop.	lda #wInMenuBar	Not on the desktop flag, just in case.	plx	beq exit1;;; ------ We're on the desktop.  Are we on a window? ------------------------;ck_wind	ldx <topwind	Start at top and check every window.	lda <topwind+2	bra enter1;lop1	jsr testVis	Test the window's F_VIS flag.	beq next1	Check only visible windows.;	lda point+x1,s	Past point to check.	tax	lda point+y1,s	jsr findloc	Check if on a window part.	tax	beq next1	On any part of window?;	sta retLoc,s	Save part found.	ldy #wport+4	Set the system/nonsystem window	lda [<wind],y	flag in the part code.	and #$8000	ora retLoc,s	bra exit1;next1	ldy #wnext	Check the next window.	lda [<wind],y	tax	iny	iny	lda [<wind],yenter1	sta <wind+2	stx <wind;	ora <wind	bne lop1	Any more windows to	check?;;    On desktop, but not on any window,	flag is zero.;	lda #wInDesk;exit1	sta retLoc,s	Return location to caller.;	lda retWind,s	Return window pointer.	sta <workptr	lda retWind+2,s	sta <workptr+2;	jsr get_portptr	Convert 'wind' to port pointer.	sta [<workptr]	ldy #2	txa	sta [<workptr],y;	phb	brl pop8bytes	ENDP;;;=======================================;        Find point	on window.;=======================================;;  IN:   a = y point in global.;        x = x point in global.;        wind = window to check.;; OUT:     a =   Zero if not on anything.;                wInContent if in content region.;                wInDrag if in drag region.;                wInGrow if in grow region.;                wInGoAway if in go-away region.;                wInZoom if in zoom region.;                wInInfo;                wInVScroll;                wInHScroll;                wInFrame;findloc	PROC;		;using equates;;	sta <yrat	Save point.	stx <xrat;;; --- Check for hit	on window --------------------------------;	ldy #wstrucRgn+2	jsr test_pt	Is the point on the	window?	bne next1;	lda #0	Not on window flag.	rts;;; --- Point is on the window, now find out where -------------;next1	ldy #wcontRgn+2	Is the point on the	content region?	jsr test_pt	beq next2;	lda #wInContent	On content.	rts;;; --- Check other regions on window --------------------------;next2	jsr getwgrect	wrect = window's strucRgn bounds (global).;	lda <yrat	Convert point to check to window's local.	sec	sbc <wrect+y1	sta <param;	lda <xrat	sec	sbc <wrect+x1	sta <param+2;	jsr moveWMgrOnWind	Move Window Manager	over window.;	ldx #wHit	Check hit message.	jsr dispatch	Call window definition procedure.	pha;	jsr moveWMgrBack	Put Window Manager's port back.;	pla	rts	ENDP;;;===============================================;        Check if a	point is in a region.;===============================================;;   IN:  yrat = y point.;        xrat = x point.;        wind = window to check.;        y = offset	into window record where region handle is.;;  OUT:  Equal = FALSE if point is in region.;test_pt	PROC;	pha	Space for returned value.	jsr pushyrat	Pass pointer to point to check.	jsr pushandle	Pass handle of region to check.	_PtInRgn	pla	Get result which sets return flag.	rts	ENDP;;;=====================================;        Check point inside rect.;=====================================;;   IN:  a = y position.;        x = x position.;        rect = rectangle to check.;;  OUT:  if inside equal = FALSE, 'A' and 'Y' = 1.;        if not inside equal = TRUE, 'A' and 'Y' = 0.;inside	PROC;		;using equates;;	ldy #0	Not inside flag.;	bit <rect+y1	Is top side off top	of screen?	bmi ok1	cmp <rect+y1	Below top side?	bcc exit1ok1	bit <rect+y2	Is bottom off top?	bmi exit1	cmp <rect+y2	Above bottom side?	bcs exit1;	bit <rect+x1	bmi ok2	cpx <rect+x1	To right of left side?	bcc exit1ok2	bit <rect+x2	Is right side off left side of screen?	bmi exit1	cpx <rect+x2	To left of right side?	bcs exit1;	iny	Set inside flag.;exit1	tya	Set return equal flag.	rts	ENDP;;;===================================;        Watch Zoom	Box.;===================================;;   IN:    PUSH:LONG - y,x starting point of cursor in global coordinates.;          PUSH:LONG - pointer to window port.;;  OUT:    WORD - TRUE if button released inside zoom box, else FALSE.;TrackZoom	PROC;;theWind	equ 9point	equ theWind+4retFlag	equ point+4;;	jsr setup;	lda #wInZoom	Zoom box flag.	bra trackbox;;; = = = = = = = = =	= = = = = = = = =;        Watch Box.; = = = = = = = = =	= = = = = = = = =;;   IN:    PUSH:LONG - y,x starting point of cursor in global coordinates.;          PUSH:LONG - pointer to window port.;;  OUT:    WORD - TRUE if button released inside close box,	else FALSE.;	ENTRY TrackGoAwayTrackGoAway		;       ;;	jsr setup;	lda #wInGoAway	Close box flag.;	ENTRY trackboxtrackbox		;       ;	sta <boxflag	wInGoAway or wInZoom.;	lda #0	Starts out as normal.	sta retFlag,s;	jsr clipabove	jsr moveWMgrOnWind	Move Window Manager	over window.;	lda point,s	Pass local coordinates to defProc.	sta <param	lda point+2,s	sta <param+2;	jsr pushparam	_GlobalToLocal;;	jsr ck_inbox	Check if rat in box.	lda retFlag,s	Must start out in box.	beq exit;;lop1	jsr ckbutton	Check for a button up event.	sty <param	sta <param+2	bne released	Done if button up.;	jsr ck_inbox	Check if rat in box.	bra lop1;;; --- Button has been released ------------------------------------;released	jsr ck_inbox	Check if still in box.;	lda #0	Always exit with box as normal.	jsr drawbox;;exit	jsr moveWMgrBack	Put Window Manager's port back.	phb	brl pop8bytes;;; = = = = = = = = =	= = = = = = = = = =	=;          Check if	rat in box.; = = = = = = = = =	= = = = = = = = = =	=;;   IN:    <param =	position to check, in local.;          <boxFlag	= wInGoAway or wInZoom.;;  OUT:    retFlag = TRUE if in box, FALSE if outside box.;ck_inbox	ldx #wHit	Pass hit test window command.	jsr dispatch	Call defProc.;	ldx #0	Not in box flag, just in case.	cmp <boxFlag	In proper part?	bne store100	ldx #TRUE	In box flag.store100	txa	cmp retFlag+2,s	Has state changed?	beq exit100;	sta retFlag+2,s	New state.;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = =;          Ask window defProc to draw close or zoom box.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= = = =;;   IN:    a = 0 to	unhilite box, $8000	to hilite.;          <boxFlag	= wInGoAway to draw	close box, wInZoom to draw zoom box.;drawBox	pei <param+2	Save.	pei <param;	sta <param+2	Pass hilite flag.	lda <boxFlag	sec	sbc #wInGrow	Convert wInGoAway to 1, wInZoom to 2.	sta <param	Pass part to draw.;	pei <wrect+y2	Save.	pei <wrect+x2;	ldx #wDraw	Pass draw command to defProc.	jsr dispatch;	pla	Restore.	sta <wrect+x2	pla	sta <wrect+y2	stz <wrect+y1	stz <wrect+x1;	pla	Restore.	sta <param	pla	sta <param+2;exit100	rts;	ENDP;;;=============================================;        Bring a window to the front.;=============================================;;   IN:  PUSH:LONG - window port to bring to front.;;  OUT:  Nothing.;BringToFront	PROC;	jsr setup;	lda #0	Don't do any highlighting flag.	bra tofront	Execute common code.	ENDP;;;========================================;        Make Window the top window.;========================================;;   IN:  PUSH:LONG - pointer to the window port to become top.;;  OUT:  None.;;; Change History** Feb 89	David Good** Changed a bunch of stuff to make it go faster.** 19 Apr 89	David Good** Made vis region equal to the intersection of Gray and* content regions instead of just content.  Fixed a number * fun and hard to track bugs.*****************************************************************SelectWindow	PROC;---------------------------------------------------------------	DefineStackorigD	wordRTL1	block 3RTL2	block 3theWindow	long;---------------------------------------------------------------;---------------------------------------------------------------	jsl  IncBusyFlg	phd		;save the user's direct page pointer	tcd		;switch to our direct page	lda  theWindow,s		;make the window we are selecting a window	sec		;..pointer and put in in <workptr	sbc  #4	sta  <workptr	lda  theWindow+2,s	sbc  #0	sta  <workptr+2;---------------------------------------------------------------checkList	ldax <topwind		;check to make sure the window we are	bra  @enter		;..selecting is in the list@loop	lda  <wind	cmp  <workptr	bne  @1	lda  <wind+2	cmp  <workptr+2	beq  @foundIt@1	ldy  #2		;move to the next window	lda  [<wind],y	tax	lda  [<wind]@enter	stax <wind	ora  <wind+2		;check to see if there are more windows	bne  @loop		;..in the list. If not, then exit	brl  exit@foundIt	jsr  testVis		;if the window is invisible, then call the	beq  gotoAirport		;..airport	ldax <topwind		;are we selecting the topmost window ?	cmp  <wind		;..if so, then call the airport	bne  @notTheTop	cpx  <wind+2	beq  gotoAirport@notTheTop	stax <wind	jsr  testVis		;is the topmost window invisible ? If so,	beq  gotoAirport		;..then call the airport	lda  [<wind],y		;is the topmost window hilighted ? If so,	and  #F_HILITED		;..then we can do things the fast way	bne  doFast;---------------------------------------------------------------gotoAirport	ldax <workptr		;copy <workptr to <wind	stax <wind	lda  #1		;do highlighting flag.	ENTRY tofronttofront	ldx  #$FFFF		;move window to top flag.	txy	jsr  airport		;change window's plane.	brl  exit;---------------------------------------------------------------doFast	jsr  setwmgrport		;switch to the window manager's port	jsr  fullport		;set the clip region to a full port	jsr  unhilite		;clear the hilight bit on the topmost window	jsr  deactivate		;send deactivate message to 'wind'.		jsr  drawEntireFrame	;draw the frame as unhilighted	ldy  #wStrucRgn+2		;get the structure region into work	lda  [<workptr],y	sta  <work+2	dey	dey	lda  [<workptr],y	sta  <work	lda  <topwind		;start with the topmost window	ldx  <topwind+2;---------------------------------------------------------------mainLoop	stax <wind		;the window we are working with goes in	cmp  <workptr		;..<wind. Is it the same as the window	bne  @1		;..we are moving to the top ? If it is	cpx  <workptr+2		;..then stop changing visible regions	beq  @done@1	jsr  testVis		;is this window invisible ? If so, then	beq  @skip		;..skip it	ldax <work		;make the structure region local to the	jsr  offsetToLocal		;..window	ldy  #wport+GP_VisRgn+2	;the visible region is the old visible	jsr  pushandle		;..region minus the entire struct region	pei  <work+2		;..of the window that moved up	pei  <work	ldy  #wport+GP_VisRgn+2	jsr  pushandle	_DiffRgn	ldax <work		;make the structure region global again	jsr  offsetToGlobal@skip	ldy  #2		;get the next window ptr into A and X	lda  [<wind],y		;..wNext is zero, so take advantage of	tax		;..this	lda  [<wind]	bra  mainLoop@done	jsr  outoflist		;take the new topmost window out of the	lda  #$FFFF		;..list and put it back on top	sta  <workptr	sta  <workptr+2	jsr  intolist;---------------------------------------------------------------calcUpdateRgn	jsr  alloc_rgn		;allocate a temp work region in <rgnptr	ldy  #wport+GP_VisRgn+2	;offset the visible region to global	lda  [<wind],y		;..coordinates	tax	dey	dey	lda  [<wind],y	jsr  offsetToGlobal	ldy  #wContRgn+2		;the new update region is the difference	jsr  pushandle		;..between the content region and the	ldy  #wport+GP_VisRgn+2	;..old visible region	jsr  pushandle	pei  <rgnptr+2	pei  <rgnptr	_DiffRgn	pei  <rgnptr+2		;add the new update area to the old	pei  <rgnptr		;..update region	ldy  #wUpdateRgn+2	jsr  pushandle	ldy  #wUpdateRgn+2	jsr  pushandle	_UnionRgn	ldy  #wContRgn+2		;set the new visible region to the	jsr  pushandle		;..intersection of the content region	jsr  pushGray		;..and the desktop	ldy  #wport+GP_VisRgn+2	jsr  pushandle	_SectRgn	ldy  #wport+GP_VisRgn+2	;offset the visible region back to local	lda  [<wind],y		;..coordinates	tax	dey	dey	lda  [<wind],y	jsr  offsetToLocal	jsr  hilite		;hilight the new topmost window	jsr  activate		;send activate message to 'wind'.	jsr  drawEntireFrame	;draw the new window frame 	pei  <rgnptr+2		;erase the new update area	pei  <rgnptr	ldax <wind	clc	adc  #wport+GP_BkPat	bcc  @1	inx@1	phx	pha	_FillRgn	jsr  disposeRgnPtr		;dispose of the temporary region	jsr  restore_port		;restore original port.;---------------------------------------------------------------exit	phb	brl pop4bytes		;pop input parameters and return.;---------------------------------------------------------------	ENDP****************************************************************WindXXXProc	PROC  ENTRY;---------------------------------------------------------------	ENTRY  offsetToLocal	ENTRY  offsetToGlobal;---------------------------------------------------------------;---------------------------------------------------------------offsetToLocal	PushAX	ldy  #wport+GP_Bounds+x1	jsr  pushWlong	bra  offsetIt;---------------------------------------------------------------offsetToGlobal	PushAX	ldy  #wport+GP_Bounds+x1	lda  [<wind],y	eor  #$FFFF	inc  a	pha	dey	dey	lda  [<wind],y	eor  #$FFFF	inc  a	phaoffsetIt	_OffsetRgn	rts;---------------------------------------------------------------	ENDP****************************************************************drawEntireFrame	PROC  ENTRY;---------------------------------------------------------------	jsr  moveWMgrOnWind		;setup for drawing the frame	stz  <param		;pass 'draw entire frame' flag.	stz  <param+2		;pass 'unhilited' flag.	ldx  #wDraw	jsr  dispatch	brl  moveWMgrBack		;restore the clip region;---------------------------------------------------------------	ENDP****************************************************************;;==============================================;        Send a window behind another one.;==============================================;;   IN:  PUSH:LONG - pointer to window in front of first given window,;	   or -2 to put it on the bottom.;        PUSH:LONG - pointer to the window's port.;  OUT:  None.;SendBehind	PROC;;;	jsr setup	Get 2 pointers of input.;	jsr fixworkptr	tay	Pass which window wind goes behind.	lda #1	Perform hiliting flag.	jsr airport;	phb	brl pop8bytes;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;          Make workptr a window pointer.;100= = = = = = = =	= = = = = = = = = =	= = = = =;;   IN:    workptr = window port pointer.;;  OUT:    workptr = window pointer.;          a = workptr.;          x = workptr+2.;	ENTRY fixworkptrfixworkptr		;       ;	lda <workptr	ldx <workptr+2	Was a window pointer passed?	bmi exit100;	sec	Make window pointer	a record pointer.	sbc #wport	bcs store100	dex;store100	sta <workptr	stx <workptr+2exit100	rts;	ENDP;;;==================================================;          Change window plane and redraw.;===================================================;;   IN:    a = $xxx1 to doing hiliting/unhiliting, $xxx0 to	not.;              $8xxx if window was invisible, $0xxx if window was visible.;          x/y = window to put <wind behind.;                $FFFFFFFF to move <wind to top.;                $FFFFFFFE to move <wind to bottom.;          <wind = window to send behind, if invisible no drawing done.;;  OUT:  None.;airport	PROC;nextWindow	equ 1behind	equ nextWindow+4dohilite	equ behind+4;;	pha	1=hilite, 0=don't do hiliting.;	sty <workptr	Save behind parameter.	stx <workptr+2	phx	phy;	ldy #wNext+2	Save window under one being changed.	lda [<wind],y	pha	lda [<wind]	pha;;; --- Get copy of visible window that I	beginnin with --------------------;	jsr setwmgrport	Swicth to Window Manager's port.;	jsr alloc_rgn	Allocate a temp work region.;	lda dohilite,s	Did the window start as invisible?	bmi skip1;	jsr testVis	If window is invisible don't do drawing.	beq skip1;	ldy #wstrucRgn+2	Clone window's region.	jsr pushandle	jsr pushclip	_CopyRgn;	jsr clipabove	Subtract all windows above 'wind'.;	jsr pushclip	Clone beginning visible window part.	jsr pushrgnptr	rgnptr = beginning visible window.	_CopyRgn;;; --- Reorder window list ---------------------------------------------;skip1	jsr outoflist	Remove 'wind' from window list.	bpl ok1	Was 'wind' in the list?	brl exit;ok1	lda behind,s	Pass window to send	'wind' behind.	sta <workptr	lda behind+2,s	sta <workptr+2	jsr intolist	Put 'wind' into proper plane.;;; --- Compute the area of the screen that changed -----------------------;	jsr testVis	If window is invisible don't do drawing.	bne @ok2	brl exit@ok2;	lda #$FFFF	cmp behind,s	bne @toBottom	cmp behind+2,s	bne @toBottom;	lda nextWindow+2,s	Compute visRgns to where new top window came from.	tax	lda nextWindow,s	bra @ok1;@toBottom	inc a	Compute visRgns for every window.	tax@ok1	jsr calc_vis	Compute visRgns.;;	ldy #wstrucRgn+2	Clone window's region.	jsr pushandle	jsr pushclip	_CopyRgn;	jsr clipabove	Subtract all windows above 'wind'.;	jsr pushrgnptr	Beginning visible window.	jsr pushclip	Visible window after plane change.	jsr pushrgnptr	Result in clobbered	region.	_XorRgn	Compute the part that changed.;;; --- Unhilite/Hilite as needed, and add frames to clobbered region --------;skip2	lda dohilite,s	Did caller want hiliting changes?	and #$0001	beq exit1;	stz <work	Set top window not found flag.;	lda <topwind	ldx <topwind+2	bra enter1;lop1	jsr testVis	Test the window's F_VIS flag.	beq nextwind	If not, skip it.;	lda [<wind],y	and #F_HILITED	Get hilite bit.	ldx <work	Has the first visible window been found?	bne ck_unlite	If yes, this window	should be unhilited.;	tax	Is the window hilited?	bne exit1	If yes, top still top, clobbered ready.;	inc <work	Set 'top window found' flag.;	jsr hilite	Hilite the new top window.	jsr activate	Send activate message to 'wind'.	bra plusFrame	Add window's frame to clobbered area.;ck_unlite	tax	Is inactive window unhilited?	beq nextwind	If yes, it hasn't changed states.;	jsr unhilite	Clear hilite bit.	jsr deactivate	Send deactivate message to 'wind'.;plusFrame	jsr addframe	Add window's frame to clobbered region.;nextwind	ldy #2	lda [<wind],y	tax	lda [<wind];enter1	sta <wind	stx <wind+2	ora <wind+2	Any more windows?	bne lop1;;          exit1	lda <topwind	Start with first window in list.	sta <wind	lda <topwind+2	sta <wind+2;	jsr paintonedown	Draw all windows in	clobbered region.;exit	jsr disposeRgnPtr	Free temp work region.;	jsr zeroOrigin	SetOrigin( 0,0,).	jsr restore_port	Restore original port.;	pla	pla	pla	pla	pla	rts	ENDP;;;===========================================================;        Add window's frame region to rgnptr region.;===========================================================;;   IN:    wind = window frame to add.;;  OUT:    rgnptr =	rgnptr + wind's visible frame.;          Window Manager's clip region is trashed.;addframe	PROC;		;using equates;;; --- Compute area of frame to draw -----------------------------------------;	ldy #wstrucRgn+2	jsr pushandle	ldy #wcontRgn+2	jsr pushandle	jsr pushclip	_DiffRgn	clip = wstrucRgn - wcontRgn.;	jsr clipabove	Remove any windows above.;	jsr pushrgnptr	jsr pushclip	jsr pushrgnptr	_DiffRgn	clobbered = clobbered - visible frame.;;; --- Redraw frame ----------------------------------------------------------;	brl drawframe	ENDP;;;========================================;        Make a window visible.;========================================;;   IN:  PUSH - LONG - pointer to the window port.;  OUT:  None.;;        If the window isn't going to be the top visible window;              then	just call ShowHide.;        Else;              call	SelectWindow:;		Unhighlight current	top window.;		Moves the window to	the top of list.;              call	ShowHide to make the window visible.;ShowWindow	PROC;;	jsr setup;	jsr testVis	Test the window's F_VIS flag.	bne exit100	Is the window already visible?;;; --- Is the window	going to be the active window? ----;	lda <topwind+2	ldx <topwindlop100	cmp <wind+2	Are we at the window?	bne next100	cpx <wind	beq newtop	The window is in front of the;	                  current active window.next100	stx <workptr	sta <workptr+2;	ldy #wframe	Is this window visible?	lda [<workptr],y	and #F_VIS	bne justshowit	The window is not in front of;	                  current active window.;	lda [<workptr]	tax	ldy #wnext+2	ora [<workptr],y	Is the window event	in the list?	beq exit100;	lda [<workptr],y	bra lop100;;; --- Window is going to be the new active window. ----;newtop	ldy #wframe	lda [<wind],y	ora #F_VIS	Set visible flag.	sta [<wind],y;;	                  VisRgn must be empty.;	lda #$8001	Window was invisible, do hiliting.	ldx #$FFFF	Make the window top.	txy	jsr airport	bra exit100;;; --- Show the window. -----------------;justshowit	pea F_VIS	Make window visible.	jsr get_portptr	phx	pha	_ShowHide;;exit100	phb	brl pop4bytes	Pop input parameters and return.	ENDP;;;============================;        Hide a window.;============================;;   IN:    PUSH:LONG - pointer to window's port.;;  OUT:    None.;;          Hide the	window.;          Select a	new active window if the hidden window was active.;HideWindow	PROC;		;using equates;theWind	equ 9;;	jsr setup;	jsr testVis	Test the window's F_VIS flag.	beq exit100;	jsr find_top	Find top most visible window.;	                  and make it the new top window.;	jsr get_portp2	Get pointer to window's port.	phx	Save.	pha;	pea 0	Hide window.	lda theWind+8,s	Pass window pointer.	pha	lda theWind+8,s	pha	_ShowHide;;; --- Was the window the active window?	----;	pla	Get saved prior top	window.	plx	cpa theWind,s	Did I just hide the	top window?	bne exit100	txa	cmp theWind+2,s	bne exit100	Don't worry, I didn't hide the top window.;	jsr find_top	Find the next visible window,;	                  and make it the new top window.	beq exit100	Are there any windows left?;	jsr get_portp2	Pass pointer to window's port.	phx	pha	_SelectWindow;exit100	phb	brl pop4bytes	ENDP;;;===================================;        ShowHide a	window.;===================================;;   IN:  PUSH - WORD - FALSE to hide, TRUE to show.;        PUSH - LONG - pointer to window port.;;        If flag is	already in the requested state then just exit.;        Else;              Put visible flag into desired state.;              Redraw affected screen area.;;ShowHide	PROC;;theWindow	equ 9vis_flag	equ theWindow+4;;	jsr setup;;; --- Is the caller	requesting the visible state change? ---;	lda vis_flag,s	beq store1	lda #F_VISstore1	sta <workptr	tax;	jsr testVis	Get the window's F_VIS flag.	eor <workptr	beq exit100	No change if zero.;; --- Change visible flag ------;	lda [<wind],y	eor #F_VIS	Flip visible flag.;	cpx #0	Hiding window?	bne store2;	and #_F_HILITED	Unhilite window to be hidden.;store2	sta [<wind],y;	txa	Hiding window?	bne skip2;	ldy #wport+GP_VisRgn+2 Set window's VisRgn to empty.	jsr pushandle	_SetEmptyRgn;;    ; --- Redraw affected screen area -----;skip2	jsr setwmgrport	Swicth to Window Manager's port.;	ldy #wstrucRgn+2	Pass window's region.	jsr pushandle	jsr pushclip	Pass handle of wmgr	clip region.	_CopyRgn	Clip = window region.;	jsr clipabove	Subtract windows above 'wind' from clip.	bne skip1;	jsr alloc_rgn	Get temp. region, for clobbered region.;	jsr pushclip	Pass handle of clip	(clobbered) region.	jsr pushrgnptr	Pass handle of real	clobbered region.	_CopyRgn	Clone clobbered region.;	lda <topwind	Redraw all windows	sta <wind	lda <topwind+2	sta <wind+2	jsr paintonedown	in clobbered region.;	jsr disposeRgnPtr	Free temp. clobbered region.;skip1	jsr calc_vis	Compute visible regions for every window.;	jsr restore_port	Restore original port.;exit100	phb	brl pop6bytes	ENDP;====================================================;          Send a activate message to window.;====================================================;;   IN:    wind = window to activate.;	import ToolboxPatcheractivate	PROC	ldx #oWMActivate	jml ToolboxPatcher	EXPORT RealWMActivateRealWMActivate	inc <FlgActive	Set activate event flag.	jsr get_portptr	Get port pointer of	'wind'.	sta <CurActive	Set window that's activated.	stx <CurActive+2	rts	ENDP;====================================================;          Send a deactivate message to	window.;====================================================;;   IN:    wind = window to deactivate.;	import ToolboxPatcherdeactivate	PROC	ldx #oWMDeActivate	jml ToolboxPatcher	EXPORT RealWMDeActivateRealWMDeActivate	inc <FlgDeActive	Set deactivate event flag.;	jsr get_portptr	Get port pointer of	'wind'.	sta <CurDeActive	Set window that's deactivated.	stx <CurDeActive+2	rts	ENDP;====================================================;        Set/Clear Highlight bit in top;        window frame and redraw frame.;====================================================;;   IN:    wind = window to hilite or unhilite.;hilite	PROC;		;using equates;;	ldy #wframe	lda [<wind],y	ora #F_HILITED	Set highlight bit.	bra common;	ENTRY unhiliteunhilite		;       ;	ldy #wframe	lda [<wind],y	and #$FFFE	Clear highlight bit.;common	sta [<wind],y;	rts	ENDP;;;===================================================;        Take a window out of the list.;===================================================;;   IN:    wind = window to take out of	list.;;  OUT:    Neg = TRUE if window not in list.;;outoflist	PROC;		;using equates;;	jsr getpre	bmi exit100	Window not in list?	php	Save status.;;   wind = window to take out of list.;   workptr = window in front of wind (might be address of 'topwind').;	ldy #wnext	lda [<wind],y	sta [<workptr],y	iny	iny	lda [<wind],y	sta [<workptr],y;	plp	Return status of 'getpre'.;exit100	rts	ENDP;;;=============================================;        Insert a window into the list.;=============================================;;   IN:    wind = window to be inseted,	must not be currently in list.;          workptr = window where wind will be inserted behind.;	 $FFFFFFFF to insert as top most.;	 $FFFFFFFE to insert as bottom most.intolist	PROC;		;using equates;;	lda <workptr+2	Window pointer or specical command?	bpl insertit	Must be a window pointer.;	lda <workptr	Should window go to	the bottom?	cmp #$FFFE	beq tobottom	If negative and not	-2, must be -1.;;; ------ Insert as top window ---------------------------;	ENTRY wind2topwind2top		;       ;	stz <workptr+2	Set to address of 'topwind'.	tdc	clc	adc #topwind	sta <workptr	bra insertit;; ------ Insert under bottom window ---------------------;tobottom	stz <workptr+2;	ldx <topwind	Start at top and work down.	lda <topwind+1	beq wind2top;	ldy #wnext+1lop100	stx <workptr	sta <workptr+1;	lda [<workptr]	Next window.	tax	lda [<workptr],y	bne lop100;;; --- Insert the window ---------------------------------;;  wind = window to	be put under.;  workptr = window	to be in front of 'wind'.;insertit	ldy #wnext+2	Insert window back in list.	lda [<workptr],y	sta [<wind],y	lda <wind+2	sta [<workptr],y;	lda [<workptr]	sta [<wind]	lda <wind	sta [<workptr];	rts	ENDP;;;====================================================;        Highlight or Unhighlight a window.;====================================================;;  IN:   PUSH - WORD - TRUE = highlight	the window.;	   FALSE = unhighlight the window.;        PUSH - LONG - pointer to the window's port.;HiliteWindow	PROC;;;	jsr setup;	jsr setwmgrport	Switch to Window Manager's port.;	lda <workptr	Highlight or Unhighlight?	bne liteit;	jsr unhilite	Clear highlight bit	in frame.	bra skip;liteit	jsr hilite	Set highlight bit in frame.;skip	ldy #wstrucRgn+2	Pass handle window's StructRgn.	jsr pushandle	jsr pushclip	Pass clip region handle.	_CopyRgn	Set clip to window.;	jsr clipabove	Clip to above windows.;	jsr drawframe	Draw window's frame.;	jsr restore_port	Restore original port.;	phb	brl pop6bytes		ENDP;;;====================================;        Draw window's frame;        and do setup.;====================================;;   IN:    current port = Window Manager's.;          wind = window to draw.;drawframe	PROC;		;using equates;;	jsr moveWMgrOnWind	Move Window Manager	over window.;	ldy #justInfo	lda [<data],y	beq store1	lda #3	Draw just the info bar.store1	sta <param	Pass 'draw entire frame' flag.	stz <param+2	Pass 'unhilited' flag.	ldx #wDraw	jsr dispatch;	brl moveWMgrBack	Put Window Manager's port back.	ENDP;;;========================================;        Move 'wrect' into 'rect';========================================;wrect2rect	PROC;		;using equates;	ldx #x2lop	lda <wrect,x	sta <rect,x	dex	dex	bpl lop	rts	ENDP;;;          APPEND WUTIL.ASM	TITLE 'Apple IIGS Window Manager                   WUTIL.ASM';;          Copyright Apple Computer, Inc. 1986,1987,1988;          All rights reserved;          Written by Dan Oliver;;;==========================================================;          Move Window Manager's port on window.;==========================================================;;   IN:    <wind = pointer to window record.;moveWMgrOnWind	PROC;;;	jsr setwmgrport	Switch to Window Manager's port.;;; --- Set up Window	Manager port over window -----------------;	jsr getwgrect	wrect = window's strucRgn bounds (global).;;; --- Make Window Manager's origin the same as window's screen origin ----;	lda <wrect+x1	eor #$FFFF	inc a	tax	lda <wrect+y1	eor #$FFFF	inc a	jsr setTheOrigin;	jsr pushclip	Offset clipping region.	lda <wrect+x1	eor #$FFFF	inc a	pha	lda <wrect+y1	eor #$FFFF	inc a	pha	_OffsetRgn;;; --- Put window's frame controls in Window Mgr window record -----------;	ldy #wFrameCtls	lda [<wind],y	tax	iny	iny	lda [<wind],y	ldy #wmgr_wind+wControls+2	sta [<data],y	dey	dey	txa	sta [<data],y;	ldy #wFrame	lda [<wind],y	and #_F_CTL_TIE	Force state of controls to be window's.	ldy #wmgr_wind+wFrame	sta [<data],y;	rts	ENDP;;;===========================================================;          Back Window Manager port back to global.;===========================================================;moveWMgrBack	PROC;;;	jsr pushclip	Offset clipping region back.	ldy #port+GP_Bounds+x1lop1	lda [<data],y	eor #$FFFF	inc a	pha	dey	dey	cpy #port+GP_Bounds+y1	beq lop1	_OffsetRgn;	jsr zeroOrigin	SetOrigin( 0,0,).	brl restore_port	ENDP;;;======================================================;          Call window's definition procedure.;======================================================;;   IN:    x = operation number.;          wind = window affected.;          param = additional parameter.;;  OUT:    x/a = returned value from defProc.;dispatch	PROC;		;using equates;;	ldy #wdefProc+1	Pass address of defProc.	lda [<wind],y	pha	dey	lda [<wind],y	ply;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =;          Call a defProc at a given address.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = =;;   IN:    x = operation number.;          a = low word of address.;          y = middle word of address.;          wind = window affected.;          param = additional parameter.;;  OUT:    x/a = returned value from defProc.;	ENTRY dispatch2dispatch2		;       ;	pha	Space for return.	pha	pei <data+2	Pass pointer to Window globals.	pei <data	phx	Operation number to	perform.	pei <wind+2	pei <wind	pei <param+2	Pass parameter.	pei <param;	                  a	= low word of address.	tyx	x = mid word of address.	jsl longCall	Call defProc.	pla	Return result.	plx	rts	ENDP;;;================================================;        Switch to window manager's port.;================================================;setwmgrport	PROC;;	jsr save_port	Save current port.;	ENTRY wmgrport2wmgrport2		;       ;	jsr pushport	Switch to window manager's graf port.	_SetPort	rts	ENDP;;;======================================;          Save current port.;======================================;;  OUT:    old_port	= current port, if old_port = zero on entry.;save_port	PROC;		;using equates;;;	lda <Save_Cnt;	sta >$Fd1236	inc <save_cnt;	lda <old_port	ora <old_port+2	bne exit;	pha	pha	_GetPort	pla	sta <old_port	pla	sta <old_port+2;exit	rts	ENDP;          ;;=========================================;          Restore original port.;=========================================;;   IN:    old_port	= original port, zero if no need for restore.;;  OUT:    current port = old_port.;	EXPORT restore_portrestore_port	PROC;		;using equates;;	lda <old_port	tay	ldx <old_port+2	ora <old_port+2	beq exit	No port to restore.;;	lda <Save_Cnt;	sta >$Fd1234	dec <save_cnt	bne exit;	phx	phy	_SetPort;	stz <old_port	stz <old_port+2;exit	rts	ENDP;;;============================================;          Dereference a handle.;============================================;dereference	PROC;		;using equates;;	ldy #2	Dereference the control's handle.	lda [<workptr],y	tay	lda [<workptr]	sta <workptr	sty <workptr+2	rts	ENDP;;;======================================================;       Get window pointer from current	port;======================================================;get_port	PROC;	pha	pha	_GetPort	pla	plx	brl get_wptr	Convert port pointer to window pointer.	ENDP;;;===============================================;          Find front most visible window.;===============================================;;   IN:    topwind = first window in window list.;;  OUT:    top_vis = top visible window.;          a = top_vis.;          x = top_vis+2.;          BEQ if no visible window found.;          BNE if visible window found.;	EXPORT find_topfind_top	PROC;		;using equates;;	ldx <topwind+2	lda <topwind	bra enter1;lop1	ldy #2	lda [<top_vis],y	tax	lda [<top_vis];enter1	sta <top_vis	stx <top_vis+2	ora <top_vis+2	Last window?	beq exit;	ldy #wframe	Is this window visible?	lda [<top_vis],y	and #F_VIS	beq lop1	Stop when first visible window found.;	php	lda <top_vis	ldx <top_vis+2	plp;exit	rts	ENDP;;;===============================================;        Find window in front of this one.;===============================================;;   IN:    wind = window to find window	in front of.;  OUT:    equal = TRUE  if found.;                a = low word of window's address.;                x = high word.;                workptr = window in front of the one in wind.;                wind = unchanged.;          equal = FALSE;                minus = TRUE if window	not in list.;                minus = FALSE if window is top window.;getpre	PROC;		;using equates;	lda <topwind	ldx <topwind+2;	cmp <wind	bne lop110	cpx <wind+2	bne lop110;	lda #0	Previous window is the	sta <workptr+2	address of 'topwind'.	tdc	ora #topwind	sta <workptr;	ldy #1	It's the top window flag.	rts;lop110	sta <workptr	stx <workptr+2;	ora <workptr+2	bne ok100;	ldy #$FFFF	Window not in list flag.	rts;ok100	ldy #wnext	lda <wind	cmp [<workptr],y	bne next100	iny	iny	lda <wind+2	cmp [<workptr],y	beq gotit;next100	ldy #wnext+2	lda [<workptr],y	tax	dey	dey	lda [<workptr],y	bra lop110;gotit	lda <workptr	ldx <workptr+2	ldy #0	Ok flag.errout	rts;	ENDP;;;========================================================;          Open/Close the Window Manager's port.;========================================================;openWMgrport	PROC;		;using equates;OpenPort	equ $1804	Function number for	OpenPort call.ClosePort	equ $1A04	Function number for	ClosePort call.;;	ldx #OpenPort	bra enter;;	ENTRY closeWMgrportcloseWMgrport		;       ;	ldx #ClosePort;enter	jsr pushport	Pass pointer to Window Mgr's port.	jsl $E10000	rts	ENDP;;;=================================================;          Push address in data area.;=================================================;;  OUT:    x = same	as in.;pushport	PROC;		;using equates;;	lda #port	bra enter;	ENTRY pushmyeventpospushmyeventpos		;       	lda #myevent+where	bra enter;	ENTRY pushscrn2scrnpushscrn2scrn		;       	lda #scrn2scrn	bra enter;	ENTRY pushblitdespushblitdes		;       	lda #blitdes	bra enter;	ENTRY pushblitsrcpushblitsrc		;       	lda #blitsrc	bra enter;	ENTRY pushdrag_boundpushdrag_bound		;       	lda #drag_bound	bra enter;	ENTRY pushmyeventpushmyevent		;       	lda #myevent	bra enter;	ENTRY pushslop_boundpushslop_bound		;       	lda #slop_bound	bra enter;	ENTRY pushGP_BoundspushGP_Bounds		;       	lda #port+GP_Bounds	bra enter;	ENTRY pushscreenpushscreen		;       	lda #screen	bra enter;	ENTRY pushfontHandlepushfontHandle		;       	lda #fontHandle	bra enter;	ENTRY pushCallProcListpushCallProcList		;       	lda #callProcList	bra enter;	ENTRY pushscInfopushscInfo		;       	lda #scInfo	bra enter;	ENTRY pushLocInfo1pushLocInfo1	lda #locInfo1;	ENTRY pushDataAddrpushDataAddr	enter	ply	Get return address.	pei <data+2	Pass high word (doesn't cross bank).	clc	adc <data	pha	Pass low word address.	phy	Put return address back.	rts	ENDP;;;===================================================;        Push address of zero page variables.;===================================================;pushyrat	PROC;		;using equates;;	lda #yrat	bra ok1;	ENTRY pushworkpushwork		;       	lda #work	bra ok1;	ENTRY pushwrectpushwrect		;       	lda #wrect	bra ok1;	ENTRY pushparampushparam		;       	lda #param	bra ok1;	ENTRY pushrectpushrect		;       	lda #rect	Most used.ok1	brl pushDpage	ENDP****************************************************************pushrgnptr	PROC	ply	pei  rgnptr+2	pei  rgnptr	phy	rts	ENDP****************************************************************pushGray	PROC	ply	pei  GrayRgn+2	pei  GrayRgn	phy	rts	ENDP****************************************************************;;;=================================================;        Push long value in direct page.;=================================================;pushrgn2	PROC;		;using equates;;	ldx #rgnptr2;;;;   IN:  x = offset	into zero page.;	ENTRY pushptrpushptr		;       ;	ply	Grab return address.;	lda <2,x	pha	lda <0,x	pha;	phy	Put back return address and return.	rts	ENDP;;;====================================================;          Push long value from data area.;====================================================;;   IN:    None.;;  OUT:    handle to Window Manager's clip region on stack.;pushclip	PROC;		;using equates;;	ldy #port+GP_ClipRgn+2	bra enter;;	ENTRY pushvispushvis		;       	ldy #port+GP_VisRgn+2;;enter	plx	Save return address.;	lda [<data],y	Push long from data	area.	pha	dey	dey	lda [<data],y	pha;	phx	Put return address back.	rts	ENDP;;;==================================;        Allocate a	region.;==================================;;  IN:   None.;; OUT:   rgnptr2 = what rgnptr was when	entered.;        rgnptr = handle of allocated region.;        a = low address of region handle.;        x = high address of region handle.;alloc_rgn	PROC;		;using equates;;	lda <rgnptr	Move rgnptr into rgnptr2.	sta <rgnptr2	lda <rgnptr+2	sta <rgnptr2+2;	pha	Space for returned handle.	pha	_NewRgn	Allocate a region.	pla	sta <rgnptr	Store handle of allocated region,	plx	stx <rgnptr+2	in 'rgnptr'.	rts	ENDP;;;================================================;          Allocate	a block of memory.;================================================;;   IN:    a = number of bytes to allocate.;          MyID = ID to use.;;  OUT:    x/a = handle.;allocate	PROC	IMPORT allocate2;;	ldy <MyID	brl allocate2	ENDP;;;=======================================================;        Swicth to Window Manager's zero page,;        and put input parameters into zero page.;=======================================================;;  IN:   a = zero page to switch to.;setup	PROC;;; REMOVE ME!;	pha;	txa;	sta >$FD2345;	pla; END OF REMOVAL	jsl IncBusyFlg;	plx	Get return address.	phd	Save current zero page pointer.	phx	Put return address back on stack.;	tcd	Switch to Window Manager's zero page.;;	ENTRY pullparamspullparams		;       ;	lda 15,s	Pull second to last	input parameter.	sta <workptr	lda 17,s	sta <workptr+2;	ENTRY pullparampullparam		;       ;	lda 13,s	Pull last input parameter.	tax	lda 11,s	brl get_wptr	ENDP;;;============================================;          Compute window pointer;          from port pointer.;============================================;;   IN:    a = low word of port pointer.;          x = high	word of port pointer.;;  OUT:    wind = window pointer.;          a = low word of window pointer.;          x = high	word of window pointer.;          y = trashed.;	EXPORT get_wptrget_wptr	PROC;		;using equates	tay	bne ok1	Null pointer?	txy	beq store1ok1	sec	sbc #wport	Compute pointer to window record	bcs store1	from pointer to window's port.	dexstore1	sta <wind	stx <wind+2	rts	ENDPWMInit	PROC;	ENTRY WindBootInitWindBootInit	ENTRY ReservedReserved	ENTRY RealFastExitRealFastExit       	lda #0	clc	rtl	ENDP;;;==============================================;        Push a long from window record.;==============================================;;   IN:    y = offset into window record.;          wind = pointer to window record.;pushandle	PROC;;	ENTRY pushWlongpushWlong		;       ;	plx	Get return address.;	lda [<wind],y	Put long on stack.	pha	dey	dey	lda [<wind],y	pha;	phx	Put return address back on stack.	rts	ENDP;;;===============================================;          Compute pointer to window's;          port in window's record.;===============================================;;   IN:    wind = window's pointer.;;  OUT:    a = low word port pointer.;          x = high	word of port pointer.;	EXPORT get_portptrget_portptr	PROC;		;using equates;;	ldx <wind+2	lda <wind;	EXPORT get_portp2get_portp2		;       ;	bne ok1	Is it a null pointer?	txy	beq exit;ok1	clc	adc #wport	bcc exit	inxexit	rts	ENDP;;;=============================================================;           Set 'wrect' to bounds of desktop.;=============================================================;;   IN:  None.;;  OUT:  wrect = screen coordinates of GrayRgn.;deskBounds	PROC;;	ldx <GrayRgn	lda <GrayRgn+1	bra getbounds1	Put GrayRgn bounds into 'wrect'.;;; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;        Put window's global coordinates into 'wrect'.; = = = = = = = = =	= = = = = = = = = =	= = = = = = = = = =	= =;;   IN:    wind = pointer to window.;;  OUT:    wrect = screen coordinates of window.;	ENTRY getwgrectgetwgrect		;       ;	ldy #wstrucRgn	Get pointer to window's StructRgn.;;; = = = = = = = = =	= = = = = = = = =;        Get a region's bounds.; = = = = = = = = =	= = = = = = = = =;;   IN:    wind = window record that contain region handle.;          y = index into window for region handle.;;  OUT:    wrect = bounds of region.;	ENTRY getboundsgetbounds		;       ;	lda [<wind],y	tax	iny	lda [<wind],y;;; = = = = = = = = =	= = = = = = = = =;        Get a region's bounds.; = = = = = = = = =	= = = = = = = = =;;   IN:    x = low word of region handle.;          a = middle word of region handle (bits 8-23).;;  OUT:    wrect = bounds of region.;	ENTRY getbounds1getbounds1		;       ;	stx <work	sta <work+1	That's the handle.;	ENTRY getbounds2getbounds2		;       ;	ldy #2	lda [<work],y	tay	lda [<work]	clc	adc #Rgn_Bounds	I'm after the region's bounds.	bcc getbounds3	&&	iny	&&;	ENTRY getbounds3getbounds3		;       ;	sta <work	sty <work+2	That's the pointer to bounds.;	ldy #x2	Put bounds into 'wrect'.lop1	tyx	lda [<work],y	sta <wrect,x	dey	dey	bpl lop1;	rts	ENDP;;;================================================;          Test a window's visible flag.;================================================;;  OUT:    Equal set to F_VIS state.;testVis	PROC;		;using equates;;	ldy #wframe	lda [<wind],y	and #F_VIS	Is this window visible?	rts	ENDP;;;======================================================;          Get width/height of content region.;======================================================;;   IN:    wind = window pointer.;;  OUT:    wrect+y2	= wrect's height.;          wrect+x2	= wrect's width.;          a = height;getcontwh	PROC;		;using equates;;	ldy #wcontRgn	jsr getbounds	wrect = coordinates	of content region.;;;   IN:    wrect = RECT.;;  OUT:    wrect+y2	= wrect's height.;          wrect+x2	= wrect's width.;          a = height;;	ENTRY getwrectwhgetwrectwh		;       ;	ldx #x1lop1	lda <wrect+y2,x	sec	sbc <wrect+y1,x	inc a	sta <wrect+y2,x	Get current height/width of content.	dex	dex	bpl lop1	rts	ENDP;;;            APPEND	WCOMMON.ASM	TITLE 'Apple IIGS Window Manager                   WCOMMON.ASM';;          Copyright Apple Computer, Inc. 1986,1987,1988;          All rights reserved;          Written by Dan Oliver;;  This file contains procedures that can be called from anywhere;  without depending on a direct page.;;;;;============================;          Long call.;============================;;   IN:    x = middle WORD (bits 8-23) of address of destination routine.;          a = low WORD of address of destination routine.;;  OUT:    Calling this routine is the same as:;;                jsl   (ax);;          where the low byte in 'a' is	the low byte of the	destination;          address,	and x = the next 2 bytes of the destination address.;	EXPORT longCalllongCall	PROC;	dec a	Make low word look like a return address.;	              !!! High byte of address is not decremented;	                  because the program counter doesn't wrap;	                  to the next bank!!!!;	phx	Push the high byte.	tsx	Leave only the high	byte of the address.	inx	txs;	pha	Push the low word of the address.;	rtl	Go to the address.;;  When the routine	called returns, it;  will return to the routine that called 'longCall', not here.;	ENDP;;;=======================================================;          Set origin of current port to 0,0.;=======================================================;	EXPORT zeroOriginzeroOrigin	PROC;	lda #0	tax;;; = = = = = = = = =	= = = = = = = = =;          Call SetOrigin.; = = = = = = = = =	= = = = = = = = =;;   IN:    a = new y origin.;          x = new x origin.;	EXPORT setTheOriginsetTheOrigin		;       ;	phx	pha	_SetOrigin	rts	ENDP;;;            APPEND	WSTATIC.ASM	TITLE 'Apple IIGS Window Manager                   WSTATIC.ASM';;          Copyright Apple Computer, Inc. 1986,1987,1988;          All rights reserved;          Written by Dan Oliver;;;=====================================;          Static data area.;=====================================;	EXPORT staticRAMstaticRAM	PROC;;; --- Default pattern/color table for windows ------------------;	EXPORT def_colordef_color	DC.W $0000	Frame outline.	DC.W $0F0F	Unused/Inactive Bar/Inactive Title/Title.	DC.W $0000	Title bar.	DC.W $F0F0	Inside grow box.	DC.W $00F0	Inside info bar.;;; --- Default zoom window size ---------------------------------;	EXPORT def_zoomdef_zoom	DC.W 25,30,199,639;;; = = = = = = = = =	= = = = = = = = = =	= = = = =;           Window Manager icon font.; = = = = = = = = =	= = = = = = = = = =	= = = = =;	EXPORT wind640wind640		; ;	DC.W $0006	; {offset word}	DC.W $00CE	; {FontID}	DC.W $0000	; {style}	DC.W $000A	; {size}	DC.W $0101	; {version}	DC.W $01E6	; {FBRextent};	DC.W $9001	; {FontType}	DC.W $0000	; {FirstChar}	DC.W $0002	; {LastChar}	DC.W $0013	; {WidMax}	DC.W $0000	; {KernMax}	DC.W $FFF7	; {nDescent}	DC.W $000F	; {fRectWidth}	DC.W $0009	; {FrectHeight}	DC.W $0025	; {owTLoc}	DC.W $0000	; {ascent}	DC.W $0009	; {descent}	DC.W $0000	; {leading}	DC.W $0003	; {RowWords};; BitImage:	DC.B $00,$00,$00,$00,$00,$00,$FF,$FF,$FF,$FF,$FF,$F8,$C0,$07,$9F,$CF	DC.B $06,$18,$C0,$07,$E7,$3F,$06,$18,$C0,$07,$B8,$EF,$FE,$18,$C0,$07	DC.B $E7,$3F,$00,$18,$C0,$07,$9F,$CF,$00,$18,$FF,$FF,$FF,$FF,$FF,$F8	DC.B $00,$00,$00,$00,$00,$00;; LocTable:	DC.W $0000	Close box.	DC.W $000F	Hilited close/zoom boxes.	DC.W $001E	Zoom box.	DC.W $002D	Total width of bit image in pixels.	DC.W $002D	; Total Width in Pixels;; OWTable:	DC.W $0213	; Char (00)	DC.W $0213	; Char (01)	DC.W $0213	; Char (02)	DC.W $0401	; Missing Symbol	DC.W $0000	; End of Table - (often -1);;	EXPORT wind320wind320		;       ;	DC.W $0006	; {offset word}	DC.W $00CF	; {FontID}	DC.W $0000	; {style}	DC.W $000A	; {size}	DC.W $0101	; {version}	DC.W $01F2	; {FBRextent};	DC.W $9001	; {FontType}	DC.W $0000	; {FirstChar}	DC.W $0002	; {LastChar}	DC.W $000D	; {WidMax}	DC.W $0000	; {KernMax}	DC.W $FFF7	; {nDescent}	DC.W $0009	; {fRectWidth}	DC.W $0009	; {FrectHeight}	DC.W $001C	; {owTLoc}	DC.W $0000	; {ascent}	DC.W $0009	; {descent}	DC.W $0000	; {leading}	DC.W $0002	; {RowWords};; BitImage:	DC.B $00,$00,$00,$00,$FF,$FF,$FF,$E0,$80,$DF,$62,$20,$80,$FB,$E2,$20	DC.B $80,$F5,$FE,$20,$80,$FB,$E0,$20,$80,$DF,$60,$20,$FF,$FF,$FF,$E0	DC.B $00,$00,$00,$00;; LocTable:	DC.W $0000	; Char (00)	DC.W $0009	; Char (01)	DC.W $0012	; Char (02)	DC.W $001B	; Missing Symbol	DC.W $001B	; Total Width in Pixels;; OWTable:	DC.W $020D	; Char (00)	DC.W $020D	; Char (01)	DC.W $020D	; Char (02)	DC.W $0401	; Missing Symbol	DC.W $0000	; End of Table - (often -1);	ENDP;;	Blanks off	String asis;;;==================================================================;	Create window from new template.;	it can be fetched from a resource or be passed;	by pointer or handle.;; Modified 12-dec-88 Mensch;    Added support for input verbs so that NewWindow2 can use ptrs;      and handles. Added Input verb to passed parms and template;==================================================================;;   IN:  PUSH:LONG - space for result.;        PUSH:LONG - window title.;        PUSH:LONG - refCon.;        PUSH:LONG - address of content draw routine, NIL if none.;        PUSH:LONG - address of window defProc, NIL for standard.;        PUSH:WORD - input verb defines what next long word is.;        PUSH:LONG - ID of resource that is window parameter table template.;        PUSH:WORD - type of resource that is window parameter table template.;;  OUT:  LONG - pointer to window graphPort, NIL if window not created.;NewWindow2	PROC EXPORT;	IMPORT shutdown	IMPORT allocate1	IMPORT allocate3;;; --- New window parameter list offsets.;p_length	equ 0	Number of bytes in parameter list.p_wframe	equ p_length+2	Type of window, frame flags.p_wtitle	equ p_wframe+2	Pointer to window's title.p_wrefCon	equ p_wtitle+4	Reserved for application.p_wfull	equ p_wrefCon+4	Size of window, used with ZoomWindow.p_wcolor	equ p_wfull+8	Pointer to window's color table.p_y_origin	equ p_wcolor+4	Content's vertical offset.p_x_origin	equ p_y_origin+2	Content's horizontal offset.p_data_h	equ p_x_origin+2	Height of total data area.p_data_w	equ p_data_h+2	Width of total data	area.p_wmaxheight	equ p_data_w+2p_wmaxwidth	equ p_wmaxheight+2p_vscroll	equ p_wmaxwidth+2	Amount to scroll vertically (arrows).p_hscroll	equ p_vscroll+2	Amount to scroll horizonally (arrows).p_vpage	equ p_hscroll+2	Amount to page vertically (page region).p_hpage	equ p_vpage+2	Amount to page horizontally (page rgn).p_wInfoText	equ p_hpage+2p_wInfoH	equ p_wInfoText+4	Height of infomation bar.p_wdefProc	equ p_wInfoH+2	NOT USED.p_wInfoDraw	equ p_wdefProc+4	Address of routine to draw Info Bar.p_updateDraw	equ p_wInfoDraw+4	Address of routine to draw content region.p_position	equ p_updateDraw+4p_behind	equ p_position+8p_windrec	equ p_behind+4	control template p_wInVerbs	equ p_windrec+4	Input verbs describing title,color tbl, and ctl templatep_size	equ p_wInVerbs+2;;; --- Resource types.;rPString	equ $8006rWindParam1	equ $800ErWindParam2	equ $800FrWindColor	equ $8010;;; --- Input verbEquatesresIDVAsPtr	equ 0resIDVAsHandle	equ 1resIDVAsResource	equ 2;; --- parmameter template verb word equates; the first byte is the same as the verb for NewControl2 calltitleAsPtr	equ $0000titleAsHandle	equ $0100titleAsResource	equ $0200colorAsPtr	equ $0000colorAsHandle	equ $0400colorAsResource	equ $0800;;; --- Direct page offsets.;@ID	equ 1@hand	equ @ID+4@ptr	equ @hand+4@paramPtr	equ @ptr+4@memoryID	equ @paramPtr+4;@saveDbank	equ @memoryID+2@saveDpage	equ @saveDbank+1@retAddrs	equ @saveDpage+2@resType	equ @retAddrs+6@resID	equ @resType+2@resIDVerb	equ @resID+4	; added 12/12/88 Mensch@defProc	equ @resIDVerb+2@contentDraw	equ @defProc+4@refCon	equ @contentDraw+4@title	equ @refCon+4@result	equ @title+4;	jsl IncBusyFlg	phd	Save caller's direct page pointer.	phb	Save caller's data bank pointer.;	phk	Switch data bank to program bank.	plb;	tcd	Switch to Window Manager's direct page.;	tsc	pei <MyID	Put memory ID on my page.;	sec	Switch direct page into stack.	sbc #@saveDbank-1	tcs	tcd;	stz <@result	Start with no window, just in case.	stz <@result+2;;; --- Test InputVerb to determine the method of parm passing;	lda <@resIDVerb	get the passed verb	cmp #resIDVAsResource	beq @ResIDIsRes	If passed as resource, go load it ; if neither of these, then passed by handle or pointer, first allocate temp storage; to copy the users template into	lda #p_size	template size.	ldy <@memoryID	ldx #$8000	pass attributes in <X> (Locked)	jsr allocate3	Allocate memory for template.	sta <@hand	stx <@hand+2	lda [<@hand]	deref the handle now...	tax	ldy #2	lda [<@hand],y	sta <@ParamPtr+2	stx <@ParamPtr	lda <@resIDVerb	get the res ID verb again	beq @ResIDIsPtr	if pointer, then pass it...; if it gets here the user passed us a handle, so copy the data now...	pei <@resID+2	Pass handle to copy from	pei <@resID	pei <@ParamPtr+2	pass the handle to copy to	pei <@ParamPtr	pea $0000	now pass the size	pea p_size	to copy	_handToPtr	brl @TD0010;; --- New template ref was passed by pointer, so just copy the pointer;@ResIDIsPtr	pei <@ResID+2	pointer to the source parm block	pei <@ResID	pei <@paramPtr+2	pointer to destination	pei <@paramPtr	pea $0000	pea p_size	_BlockMove	copy the data	bra @TD0010	and continue; ; --- Load new window parameter table resource.;@ResIDIsRes	pha	Space for result.	pha	pei <@resType	Pass type.	pei <@resID+2	Pass ID.	pei <@resID	_LoadResource	tay	Possible error code in y.	plx	stx <@paramPtr	plx	stx <@paramPtr+2	bcc @ok2	Error?@toExit2	brl @exit2	Error.@ok2;; Now, take the handle from resource mgr or passed by app and dereference it.@TemplateDeref	ldy #4	Lock parameter table.	lda [<@paramPtr],y	ora #$8000	sta [<@paramPtr],y	dey	Dereference the table.	dey	lda [<@paramPtr],y	tay	lda [<@paramPtr]	sta <@paramPtr	sty <@paramPtr+2@TD0010;;; --- Fix up parameter table.;	lda <@resType	Which kind of parameter table?	cmp #rWindParam1	beq @doParam1;	jsr @fixParam2	bra @done1;@doParam1	jsr @fixParam1@done1	tya	Place possible error code in A.	bcs @errOut	Error?;;; --- Have NewWindow create the window.;; First adjust parameter list count back to new window size...	lda [<@paramPtr]	remove the input verb from the parm count	dec a	dec a	sta [<@paramPtr]	pha	Save for result.	pha	pei <@paramPtr+2	Pass pointer to parameter table.	pei <@paramPtr	_NewWindow	ply	Return window pointer.	sty <@result	ply	sty <@result+2	bcc @skip1	Erorr? y = error code if any.;@errOut	pha	Save error code.;	lda <@resType	Free items allocated by me.	cmp #rWindParam1	bne @skip3	Only for parameter table type 1.;	ldy #p_wtitle+2	Free title if there is one.	jsr @freeField;	ldy #p_wcolor+2	Free the color table if there is one.	jsr @freeField;@skip3	pla	Restore error code.;;; --- Free parameter table.;@skip1	pha	Save error code.;	lda <@resIDVerb	get the passed verb	cmp #resIDVAsResource	beq @DumpRes	If passed as resource, release it...; If not a resource, then I made a copy of the passed param block and I should ; dispose of it right now...	pha	room for result	pha	pei <@paramPtr+2	first get the handle back for the temp parm block	pei <@paramPtr	_FindHandle	get the handle back	_DisposeHandle	and get rid of it.	bra @MkCtrls;@DumpRes	pea $FFFF	Pass 'dispose' flag.	pei <@resType	Pass type.	pei <@resID+2	Pass ID.	pei <@resID	_ReleaseResource;;; --- Create controls in window. Use the low order byte of the wInVerb as the;     input verb for this call.;@MkCtrls	lda <@ID	Is there a control list?	ora <@ID+2	beq @skip2;	lda <@result	Was a window created?	ora <@result+2	beq @skip2;	pha	Space for result.	pha	pei <@result+2	Pass window owner.	pei <@result	ldy #p_wInVerbs	load the offset to the template verbs	lda [<@paramPtr],y	load in the input verb	and #$00FF	strip off the high byte, low byte for this call	pha	and pass it as inputverb for NewControl2	pei <@ID+2	Pass ID of item list.	pei <@ID	_NewControl2	plx	Don't need result.	plx	bcc @skip2	Error?	sta 1,s	Replace saved error code with error from NewControl2.;@skip2	ply	Restore error code from NewWindow.;;; --- Clean up stack and exit.;      mod 12/12/88 pull off 24 bytes parameter. Mensch;@exit2	tsc	Free allocated direct page.	clc	adc #@saveDbank-1	tcs	ldx #24	Number of bytes to pop.	brl shutDown;@desIndex	dc.w p_wrefCon,p_wdefProc,p_updateDraw@srcIndex	dc.w @refCon,@defProc,@contentDraw;;;-----------------------------------------------;        Free handle in parameter table.;-----------------------------------------------;;   IN: y = index to high word of field.  If highest bit set it is a handle to free.;@freeField	lda [<@paramPtr],y	bpl @exit100;	and #$00FF	pha	dey	dey	lda [<@paramPtr],y	pha	_DisposeHandle@exit100	rts;;;---------------------------------------------------------------------;	Fix up parameter table type 1.;-200-----------------------------------------------------------------;;  OUT:  Carry set if error, y = error code.;        <@ID = ID of control list, NIL if none.;@fixParam1	stz <@ID	Start with no controls.	stz <@ID+2;;; --- Set window title in table.;	lda <@title	Was a title passed?	ora <@title+2	beq @loadTitle	Use the passed title if there is one.;;; ------ Clone the given title.;@Clonetitle	lda [<@title]	Compute size of string,	and #$00FF	inc a	including length byte.	pha	Save size.	ldy <@memoryID	jsr allocate1	Allocate fixed memory for title.	sta <@hand	stx <@hand+2;	ply	Restore size of string.;	pei <@title+2	Pass source pointer.	pei <@title	phx	Pass destination handle.	pha	pea 0	Pass number of bytes to move.	phy	_PtrToHand	Clone title.;	ldy #p_wtitle	Store handle of title.	lda <@hand	sta [<@paramPtr],y	iny	iny	lda <@hand+2	ora #$8000	Set bit that states this is a handle.	sta [<@paramPtr],y	brl @noTitle;;; ------ Load title from wherever.;@loadTitle	ldy #p_wtitle+2	Is there a title in the template?	lda [<@paramPtr],y	tax	dey	dey	ora [<@paramPtr],y	beq @noTitle;	ldy #p_wInVerbs	get the input verbs	lda [<@paramPtr],y		tay	and save em for a second	and #titleAsResource	bne @LoadTByRes	if by resource load it	tya	and #titleAsHandle	bne @LoadTByHandle	ldy #p_wtitle+2	lda [<@paramPtr],y	load the pointer	sta <@title+2	save it in the string pointer field	dey	dey	lda [<@paramPtr],y	sta <@title	brl @Clonetitle	now create a buffer and copy the title@LoadTByHandle	ldy #p_wtitle+2	lda [<@paramPtr],y	load the pointer	sta <@title+2	save it in the string pointer field	dey	dey	lda [<@paramPtr],y	sta <@title	ldy #2	lda [<@title],y	tay	lda [<@title]	sta <@title	sty <@title+2	brl @Clonetitle@LoadTByRes	ldy #p_wtitle		pha	Space for result.	pha	pea rPString	Pass type.	phx	Pass ID.	lda [<@paramPtr],y	pha	sta <@ID	Remember ID.	stx <@ID+2	_LoadResource	tay	Posible error code.	pla	plx	bcc @ok200	Error?@errOut200	rts	Error.@ok200;	ldy #p_wtitle	Store handle of title.	sta [<@paramPtr],y	iny	iny	txa	ora #$8000	Set bit that states this is a handle.	sta [<@paramPtr],y;	pea rPString	Pass type.	pei <@ID+2	Pass ID.	pei <@ID	_DetachResource	Unlink the title handle from resource.;@noTitle;;; --- Set window color table pointer in table.;	ldy #p_wcolor+2	Is there a color table resource?	lda [<@paramPtr],y	tax	dey	dey	ora [<@paramPtr],y	bne @LCT0005	brl @noColor;@LCT0005	ldy #p_wInVerbs	get the input verbs	lda [<@paramPtr],y		and #colorAsResource	bne @LoadCByRes	if by resource load it;; If not passed by resource ID we will have to make a copy of the color table; so first create a handle	lda #$0000	pha	room for result	pha	pha	zero for high word of size	pea $000A	room for a color table	pei <@memoryID	pha	zero for attributes	pha	no specific location	pha	_NewHandle	allocate the space 	tay	Possible error code.	pla	sta <@ID	save the handle for a sec...	pla	sta <@ID+2	bcs @errOut200	Error?	ldy #p_wcolor+2	push ref of the color table.	lda [<@paramPtr],y	pha	dey	dey	lda [<@paramPtr],y	pha	pei <@ID+2	address to copy to	pei <@ID	pea $0000	size to copy	pea $000A;; Now that the parms are set up properly, lets copy the right way depending on; the input verb	ldy #p_wInVerbs	get the input verbs	lda [<@paramPtr],y		and #colorAsHandle	bne @LoadCByHandle	_PtrToHand	copy the data from ptr to our handle	bra @LCT0020;@LoadCByHandle	_HandToHand	copy the data from handle to handle@LCT0020	ldy #p_wcolor+2	offset to high word of color table	lda <@ID+2	high byte of our handle	ora #$8000	set high bit to indicate by handle	sta [<@paramPtr],y	dey	dey	lda <@ID	sta [<@paramPtr],y	bra @noColor@LoadCByRes	ldy #p_wcolor	pha	Space for result.	pha	pea rWindColor	Pass type.	phx	Pass ID.	lda [<@paramPtr],y	pha	sta <@ID	Remember ID.	stx <@ID+2	_LoadResource	tay	Possible error code.	pla	plx	bcc @LCT0030	brl @errOut200	Error?;@LCT0030	ldy #p_wcolor	Store handle of the colot table.	sta [<@paramPtr],y	iny	iny	txa	ora #$8000	Set bit that states this is a handle.	sta [<@paramPtr],y;	pea rWindColor	Pass type.	pei <@ID+2	Pass ID.	pei <@ID	_DetachResource	Unlink color table handle from resource.;@noColor;;; --- Store passed values in parameter table.;	ldx #4@lop200	phx;	ldy |@desIndex,x	lda |@srcIndex,x	tax;	lda <0,x	sta [<@paramPtr],y	iny	iny	lda <2,x	sta [<@paramPtr],y;	plx	dex	dex	bpl @lop200;;; --- Get ID of control list.;	ldx #0	ldy #p_windrec	lda [<@paramPtr],y	Get the ID of the window's control list.	sta <@ID	txa	sta [<@paramPtr],y	Clear the windRec field also, window record to be 	iny	allocated.	iny	lda [<@paramPtr],y	sta <@ID+2	txa	sta [<@paramPtr],y	clc	No error.	rts;;;---------------------------------------------------------------------;	Fix up parameter table type 2.;-300-----------------------------------------------------------------;;  OUT:  Carry set if error, y = error code.;        <@ID = ID of control list, NIL if none.;@fixParam2;; --- New parameter	list offsets -----------------------------;@paramID	equ 0	ID of parameter list.@newDefProc	equ @paramID+2	DefProc of window.@newData	equ @newDefProc+4	Additional data for	new window.;;	stz <@ID	No control list.	stz <@ID+2;	ldy #@newDefProc	Store address of defProc.	lda <@defProc	sta [<@paramPtr],y	iny	iny	lda <@defProc+2	sta [<@paramPtr],y;	clc	No error.	rts;	ENDP;;;========================================================;          Dispose the temporary region;========================================================;disposeRgnPtr	PROC	pei  rgnptr+2	pei  rgnptr	_DisposeRgn	rts	ENDP;;	END